void DREAMWALK_EVENT300_NPC_REVEAL                  (CHAR_DATA *ch, CHAR_DATA *npc){
    CHAR_DATA *cre = NULL;
    CHAR_DATA *mob;
    int count = 0;

    if(!ch || !ch->in_room) return;

    if(!npc)
    {
        for(mob = ch->in_room->first_person; mob; mob = mob->next_in_room)
        {
            if(!IS_NPC(mob) ||
               xIS_SET(mob->act, ACT_PET) ||
               !can_see(ch, mob))
                continue;

            if(number_range(1, ++count) == 1)
                npc = mob;
        }
    }

    if(!npc)
    {
        npc = DREAMWALK_SPAWN_RANDOM_NPC(ch->in_room);
        if(!npc) return;

        xSET_BIT(npc->act, ACT_WORLD_SPAWN);

        CHAR_RECALCULATE_FULL(npc);
        DREAMWALK_EVENT_EQUIP_RANDOM_ITEM(ch, npc);

        DEBUG_THE_CODE(ch, npc, cre);

        if(is_affected(ch, tes_effect_dreamwalk) && can_see(ch, npc))
        {
            act(AT_PINK, "$N appears nearby.", ch, NULL, npc, TO_CHAR);
            DREAMWALK_EVENT_CALCULATE_CONSIDER_MESSAGE(ch, npc);
        }
    }
}
void DREAMWALK_EVENT400_CREATURE_REVEAL             (CHAR_DATA *ch, CHAR_DATA *cre){
    CHAR_DATA *npc = NULL;
    CHAR_DATA *mob;
    int count = 0;
    bool spawned = FALSE;

    if(!ch || !ch->in_room) return;

    if(ch->in_room->sector_type == SECT_INSIDE ||
       ch->in_room->sector_type == SECT_CITY)
    {
        if(is_affected(ch, tes_effect_dreamwalk))
            DREAMWALK_EVENT100_JUST_NOTHING(ch);

        return;
    }

    if(!cre)
    {
        for(mob = ch->in_room->first_person; mob; mob = mob->next_in_room)
        {
            if(!IS_NPC(mob) ||
               !xIS_SET(mob->act, ACT_PET) ||
               !can_see(ch, mob))
                continue;

            if(number_range(1, ++count) == 1)
                cre = mob;
        }
    }

    if(!cre)
    {
        cre = DREAMWALK_SPAWN_RANDOM_CREATURE(ch->in_room);
        if(!cre) return;

        xSET_BIT(cre->act, ACT_WORLD_SPAWN);

        CHAR_RECALCULATE_FULL(cre);
        DEBUG_THE_CODE(ch, npc, cre);

        spawned = TRUE;
    }

    if(spawned && is_affected(ch, tes_effect_dreamwalk) && can_see(ch, cre))
    {
        act(AT_PINK, "$N appears nearby.", ch, NULL, cre, TO_CHAR);
        DREAMWALK_EVENT_CALCULATE_CONSIDER_MESSAGE(ch, cre);
    }
}
//--------------------------------------------------------------------------------------------------//
void DREAMWALK_EVENT301_NPC_ATTACK                  (CHAR_DATA *ch, CHAR_DATA *npc){
    char cMSG[256];

    if(!ch || !npc || ch->fighting || npc->fighting) return;
    if(!DREAMWALK_EVENT_CHECK_SAFETY(ch)) return;
    if(!DREAMWALK_EVENT_CAN_ATTACK_NPC(ch, npc)) return;
    if(ch->in_room != npc->in_room) return;

    DREAMWALK_EVENT_CALCULATE_MORALE(ch, npc);

    sprintf(cMSG, "%sPossible actions: [%sFight%s, %sAvoid%s]",
            NrmColor, ActColor, NrmColor, ActColor, NrmColor);

    act(AT_GREY, cMSG, ch, NULL, NULL, TO_CHAR);

    if(ch->char_morale >= 70 && number_percent() <= ch->char_morale)
    {
        act(AT_YELLOW, "You decide to attack $N.", ch, NULL, npc, TO_CHAR);
        multi_hit(ch, npc, TYPE_UNDEFINED);
    }
    else
    {
        act(AT_YELLOW, "You decide to avoid $N.", ch, NULL, npc, TO_CHAR);
    }
}
void DREAMWALK_EVENT401_CREATURE_ATTACK             (CHAR_DATA *ch, CHAR_DATA *cre){
    char cMSG[256];

    if(!ch || !cre || !ch->in_room || ch->fighting || cre->fighting) return;
    if(!DREAMWALK_EVENT_CHECK_SAFETY(ch)) return;
    if(!DREAMWALK_EVENT_SAFE_TARGET(ch, cre)) return;
    if(!IS_NPC(cre) || !xIS_SET(cre->act, ACT_PET)) return;
    if(ch->in_room != cre->in_room) return;

    if(ch->in_room->sector_type == SECT_INSIDE ||
       ch->in_room->sector_type == SECT_CITY)
        return;

    DREAMWALK_EVENT_CALCULATE_MORALE(ch, cre);

    sprintf(cMSG, "%sPossible actions: [%sFight%s, %sAvoid%s]",
            NrmColor, ActColor, NrmColor, ActColor, NrmColor);

    act(AT_GREY, cMSG, ch, NULL, NULL, TO_CHAR);

    if(ch->char_morale >= 70 && number_percent() <= ch->char_morale)
    {
        act(AT_YELLOW, "You decide to attack $N.", ch, NULL, cre, TO_CHAR);
        multi_hit(ch, cre, TYPE_UNDEFINED);
    }
    else
    {
        act(AT_YELLOW, "You decide to avoid $N.", ch, NULL, cre, TO_CHAR);
    }
}
