void DREAMWALK_END                                 (CHAR_DATA *ch){
    if(!ch) return;

    CLEAN_DREAMWALK_MOBS(ch->in_room);

    affect_strip(ch, tes_effect_dreamwalk);

    if(xIS_SET(ch->affected_by, AFF_DREAMWALK))
        xREMOVE_BIT(ch->affected_by, AFF_DREAMWALK);

    ch->dreamwalk_timer = 0;
    ch->dreamwalk_supply_attempts = 0;
    ch->dreamwalk_gear_steps = ch->dreamwalk_gear_delay = ch->dreamwalk_gear_failed_vnum = 0;
    ch->automatic_dreamwalk_decision = 0;
    ch->event_type = EVENT_NONE;
}
