bool DO_GENERIC_CHECKS_C							(CHAR_DATA *ch){

    if (!ch || !ch->in_room) 						 return FALSE;
    if (!IS_AWAKE(ch))								 return FALSE;
    if (IS_AFFECTED(ch, AFF_PARALYSIS))				 return FALSE;
    if (IS_AFFECTED(ch, AFF_CHARM))					 return FALSE;	
    if (IS_CREATURE_MOB(ch))						 return FALSE;
	if (xIS_SET(ch->in_room->room_flags, ROOM_SAFE)) return FALSE;	
    return TRUE;
}
bool DO_GENERIC_CHECKS_V							(CHAR_DATA *victim){

    if (!victim || !victim->in_room) 				 return FALSE;
    if (!IS_AWAKE(victim))							 	 return FALSE;
    if (IS_AFFECTED(victim, AFF_PARALYSIS))			 	 return FALSE;
    if (IS_AFFECTED(victim, AFF_CHARM))				     return FALSE;		
    if (IS_CREATURE_MOB(victim))					     return FALSE;
	if (xIS_SET(victim->in_room->room_flags, ROOM_SAFE)) return FALSE;	
    return TRUE;
}
