bool AUTOMATIC_ARMOR_CHECK							(CHAR_DATA *ch, CHAR_DATA *victim){


	/*****************************************************************************************************************/
	/*checks the defender's equipped armor during combat.                                                           */
	/* Only the armor skill corresponding to the selected equipped item can improve.                                 */
	/* One training attempt per check, with a 10% chance, regardless of how many armor pieces are worn.              */
	/* Unarmored trains when an unprotected body location is selected.                                               */
	/*****************************************************************************************************************/
	OBJ_DATA *armor[8], *piece;
	int count = 6;
	int selection, skill;

	if(!ch || !victim || IS_NPC(victim))	return FALSE;
	if(!IS_AWAKE(victim))					return FALSE;
	if(number_percent() > 10)				return FALSE;

	//BODY LOCATIONS: six ordinary armor slots; uncovered slots permit Unarmored practice.
	//BODY LOCATIONS
	armor[0] = get_eq_char(victim, WEAR_HEAD);
	armor[1] = get_eq_char(victim, WEAR_ARMS);
	armor[2] = get_eq_char(victim, WEAR_BODY);
	armor[3] = get_eq_char(victim, WEAR_HANDS);
	armor[4] = get_eq_char(victim, WEAR_LEGS);
	armor[5] = get_eq_char(victim, WEAR_FEET);

	//OPTIONAL ARMOR LOCATIONS: a waist item/shield counts only when actually ITEM_ARMOR.
	//OPTIONAL ARMOR LOCATIONS
	piece = get_eq_char(victim, WEAR_WAIST);
	if(piece && piece->item_type == ITEM_ARMOR)
		armor[count++] = piece;

	piece = get_eq_char(victim, WEAR_SHIELD);
	if(piece && piece->item_type == ITEM_ARMOR)
		armor[count++] = piece;

	//SELECT ONLY ONE LOCATION
	selection = number_range(0, count - 1);
	piece = armor[selection];

	//DETERMINE THE ACTUAL ARMOR SKILL: armor type is value[3]; value[5] is rarity.
	//DETERMINE THE ACTUAL ARMOR SKILL
	if(!piece || piece->item_type != ITEM_ARMOR)
	{
		skill = tes_passive_armor_unarmored;
	}
	else
	{
		switch(piece->value[3])
		{
			case 1: skill = tes_passive_armor_lightarmor;	break;
			case 2: skill = tes_passive_armor_mediumarmor;	break;
			case 3: skill = tes_passive_armor_heavyarmor;	break;
			case 0: skill = tes_passive_armor_unarmored;	break;
			default:return FALSE;
		}
	}

	//TRAIN ONLY A KNOWN SKILL
	if(skill < 0 || skill >= num_skills)	return FALSE;
	if(LEARNED(victim, skill) <= 0)		return FALSE;

	learn_from_success(victim, skill);

	return TRUE;
}
bool IS_TWO_HANDED_WEAPON							(CHAR_DATA *ch){

	if(!ch) return FALSE;
	return IS_TWO_HANDED_OBJECT(get_eq_char(ch, WEAR_WIELD));
}
bool IS_TWO_HANDED_OBJECT							(OBJ_DATA *weapon){

	if(!weapon || (weapon->item_type != ITEM_WEAPON && weapon->item_type != ITEM_MISSILE_WEAPON)) return FALSE;

	//Weapon type is value[4]: 20-21 great blades, 25-26 great axes,
	//31-38 staffs/heavy blunt/polearms, 39-41 bows/crossbows.
	//Types 1-3 are THROWN weapons and must remain one-handed. value[5] is rarity.
	switch(weapon->value[4])
	{
		case 20:
		case 21:
		case 25:
		case 26:
		case 31:
		case 32:
		case 33:
		case 34:
		case 35:
		case 36:
		case 37:
		case 38:
		case 39:
		case 40:
		case 41:
			return TRUE;
	}
	return FALSE;
}
bool HAS_EQUIPPED_MARKSMAN_WEAPON					(CHAR_DATA *ch){
	OBJ_DATA *weapon;
	int slots[] = {WEAR_WIELD, WEAR_HOLD};
	int i;

	for(i = 0; i < 2; i++)
	{
		weapon = get_eq_char(ch, slots[i]);

		if(!weapon || weapon->item_type != ITEM_WEAPON) 
		continue;

		if((weapon->value[5] >= 1 && weapon->value[5] <= 3) || (weapon->value[5] >= 39 && weapon->value[5] <= 41))
		return TRUE;
	}

	return FALSE;
}
