//==================================================================================================//
// FUNCTION HELPERS                                                             					//
//==================================================================================================//
void GET_MAPPER_PLAYER_STATS						(CHAR_DATA *ch, const char **EXPcolor, const char **ATKcolor, const char **DEFcolor, const char **DMGcolor, const char **char_repColor, const char **char_reputation, int *char_exp){

	CHAR_RECALCULATE_PROMPT(ch);

	*EXPcolor = "&Y";
	if(ch->char_experience_percentage < 25) *EXPcolor = "&R";
	if(ch->char_experience_percentage > 75) *EXPcolor = "&G";

	*ATKcolor = "&Y";
	if(ch->atk_bonus < 0) *ATKcolor = "&R";
	if(ch->atk_bonus > 0) *ATKcolor = "&G";

	*DEFcolor = "&Y";
	if(ch->def_bonus < 0) *DEFcolor = "&R";
	if(ch->def_bonus > 0) *DEFcolor = "&G";

	*DMGcolor = "&Y";
	if(ch->dmg_bonus < 0) *DMGcolor = "&R";
	if(ch->dmg_bonus > 0) *DMGcolor = "&G";

	*char_exp = ch->char_experience_percentage;
	if(*char_exp <  0) *char_exp =  0;
	if(*char_exp > 99) *char_exp = 99;

	     if(ch->char_honor <= -900) {*char_repColor = "&R"; *char_reputation = "Damned";   }
	else if(ch->char_honor <= -750) {*char_repColor = "&R"; *char_reputation = "Hostile";  }
	else if(ch->char_honor <= -500) {*char_repColor = "&R"; *char_reputation = "Hated";	  }
	else if(ch->char_honor <= -250) {*char_repColor = "&O"; *char_reputation = "Despiced"; }
	else if(ch->char_honor <= -50)  {*char_repColor = "&O"; *char_reputation = "Disliked"; }
	else if(ch->char_honor >= +900) {*char_repColor = "&G"; *char_reputation = "Kindred";  }
	else if(ch->char_honor >= +750) {*char_repColor = "&G"; *char_reputation = "Exalted";  }
	else if(ch->char_honor >= +500) {*char_repColor = "&G"; *char_reputation = "Loved";	  }
	else if(ch->char_honor >= +250) {*char_repColor = "&g"; *char_reputation = "Respected";}
	else if(ch->char_honor >= +50)  {*char_repColor = "&g"; *char_reputation = "Liked";    }
	else                           {*char_repColor = "&Y"; *char_reputation = "Neutral";  }
}
void GET_MAPPER_TIME								(char *pMSG, size_t size){

	const char *suf;
	short day;

	day = time_info.day + 1;

	     if(day > 4 && day < 20)	suf = "th";
	else if(day % 10 == 1)		suf = "st";
	else if(day % 10 == 2)		suf = "nd";
	else if(day % 10 == 3)		suf = "rd";
	else						suf = "th";

	snprintf(pMSG, size,
		"It is %d o'clock %s, %s, %d%s day of %s, in the year %d.",
		(time_info.hour % sysdata.hournoon == 0)
			? sysdata.hournoon
			: time_info.hour % sysdata.hournoon,
		time_info.hour >= sysdata.hournoon ? "pm" : "am",
		day_name[time_info.day % sysdata.daysperweek],
		day,
		suf,
		month_name[time_info.month],
		time_info.year);
}
void GET_MAPPER_AREA_REPUTATION						(CHAR_DATA *ch, char *result, size_t size){

	AREA_DATA *area;
	ROOM_INDEX_DATA *room;
	CHAR_DATA *mob;
	int vnum;
	int total = 0;
	int count = 0;
	int average;
	const char *title;

	if(!ch || !ch->in_room || !result || size == 0) return;

	area = ch->in_room->area;
	result[0] = '\0';
	if(!area) {snprintf(result, size, "You are traveling through wilderness."); return;}

	for(vnum = area->low_r_vnum; vnum <= area->hi_r_vnum; ++vnum)
	{
		room = get_room_index(vnum);
		if(!room || room->area != area) continue;

		if(room->sector_type != SECT_CITY && room->sector_type != SECT_INSIDE)
		continue;

		for(mob = room->first_person; mob; mob = mob->next_in_room)
		{
			if(!IS_NPC(mob)) continue;
			if(xIS_SET(mob->act, ACT_WORLD_SPAWN)) continue;

			total += GET_PERSONAL_DISPOSITION(ch, mob);
			count++;
		}
	}

	if(count == 0)
	{
		snprintf(result, size, "You are traveling through wilderness.");
		return;
	}

	average = ((total / count) - 50) * 2;

	     if(average >=  81) title = "revered";
	else if(average >=  61) title = "esteemed";
	else if(average >=  41) title = "honored";
	else if(average >=  21) title = "admired";
	else if(average >=  11) title = "respected";
	else if(average >=   1) title = "dependable";
	else if(average ==   0) title = "a common citizen";
	else if(average >=  -9) title = "undependable";
	else if(average >= -19) title = "a scoundrel";
	else if(average >= -39) title = "a criminal";
	else if(average >= -59) title = "a villain";
	else if(average >= -79) title = "pond scum";
	else                    title = "hated";

	snprintf(result, size, "You are %s among the people of %s.", title, area->name);
}
