const char *GET_RELATION							(short score){
		 
		 if (score <= -900) return "&RDamned&D";
    else if (score <= -750) return "&RHostile&D";
    else if (score <= -500) return "&RHated&D";
    else if (score <= -250) return "&RDespiced&D";    
    else if (score <= -50)  return "&RDisliked&D";
    else if (score >= 900)  return "&GKindred&D";
    else if (score >= 750)  return "&GExalted&D";
    else if (score >= 500)  return "&GLoved&D";
    else if (score >= 250)  return "&GRespected&D";
    else if (score >= 50)   return "&GLiked&D";
    else                    return "&YNeutral&D";
}
void LOWER_TEXT										(const char *src, char *dest){			//MAKES UPPER TEXT INTO LOWER

    int i;

    if (src == NULL)
    {
        dest[0] = '\0';
        return;
    }

    for(i = 0; src[i] && i < MAX_STRING_LENGTH-1; i++)
        dest[i] = tolower((unsigned char)src[i]);

    dest[i] = '\0';
}
const char *WORD_ARTICLE							(const char *str){						//ADDS "A" OR "AN" IN FRONT OF WORD

	if (!str || !*str) return "a";

    switch (tolower((unsigned char)str[0]))
    {
        case 'a':
        case 'e':
        case 'i':
        case 'o':
        case 'u':
        return "an "; //added an empty space
    }

    return "a "; //added an empty space
}
void CHAR_SHOW_EQUIPMENT							(CHAR_DATA *ch, CHAR_DATA *victim){

	if (victim == NULL) return;

    OBJ_DATA *head     = get_eq_char(victim, WEAR_HEAD);
    OBJ_DATA *arms     = get_eq_char(victim, WEAR_ARMS);
    OBJ_DATA *cuirass  = get_eq_char(victim, WEAR_BODY);
    OBJ_DATA *hands    = get_eq_char(victim, WEAR_HANDS);
    OBJ_DATA *waist    = get_eq_char(victim, WEAR_WAIST);
    OBJ_DATA *legs     = get_eq_char(victim, WEAR_LEGS);
    OBJ_DATA *feet     = get_eq_char(victim, WEAR_FEET);
    OBJ_DATA *mainhand = get_eq_char(victim, WEAR_WIELD);
    OBJ_DATA *offhand  = get_eq_char(victim, WEAR_HOLD);

	int count3 = 0, count2 = 0, count1 = 0, count0 = 0;

	OBJ_DATA *armor[] = {head, arms, cuirass, hands, waist, legs, feet};
	int i;

	for(i = 0; i < 7; i++)
	{
		if(!armor[i])
		continue;

		switch(armor[i]->value[3])
		{
			case 0: count0++; break;
			case 1: count1++; break;
			case 2: count2++; break;
			case 3: count3++; break;
		}
	}

	const char *armor_type;
		 if(count3 >= 4) armor_type = "heavy armor"; 
	else if(count2 >= 4) armor_type = "medium armor";
	else if(count1 >= 4) armor_type = "light armor";
	else 				 armor_type = "clothing";	 

	OBJ_DATA *insignia1 = get_eq_char(victim, WEAR_FINGER_L);
	OBJ_DATA *insignia2 = get_eq_char(victim, WEAR_FINGER_R);
	
	int vnum1 = insignia1 ? insignia1->pIndexData->vnum : 0;
	int vnum2 = insignia2 ? insignia2->pIndexData->vnum : 0;
	
	const char *prompt_guild = "for no faction.";

	if(vnum1 || vnum2)
	{
         if(vnum1 == TES_OBJ_APPAREL_FIGHTERS_GUILD 	 || vnum2 == TES_OBJ_APPAREL_FIGHTERS_GUILD)       {prompt_guild = "for the Fighters guild.";}
    else if(vnum1 == TES_OBJ_APPAREL_THIEVES_GUILD 		 || vnum2 == TES_OBJ_APPAREL_THIEVES_GUILD)        {prompt_guild = "for the Thieves guild.";}
    else if(vnum1 == TES_OBJ_APPAREL_MAGES_GUILD 		 || vnum2 == TES_OBJ_APPAREL_MAGES_GUILD)          {prompt_guild = "for the Mages guild.";}
    else if(vnum1 == TES_OBJ_APPAREL_DARK_BROTHERHOOD 	 || vnum2 == TES_OBJ_APPAREL_DARK_BROTHERHOOD)     {prompt_guild = "for the Dark brotherhood.";}
    else if(vnum1 == TES_OBJ_APPAREL_IMPERIAL_LEGION 	 || vnum2 == TES_OBJ_APPAREL_IMPERIAL_LEGION)      {prompt_guild = "for the Imperial legion.";}
    else if(vnum1 == TES_OBJ_APPAREL_IMPERIAL_CULT 		 || vnum2 == TES_OBJ_APPAREL_IMPERIAL_CULT)        {prompt_guild = "for the Imperial cult.";}
    else if(vnum1 == TES_OBJ_APPAREL_BLADES 			 || vnum2 == TES_OBJ_APPAREL_BLADES)               {prompt_guild = "for the Blades.";}
    else if(vnum1 == TES_OBJ_APPAREL_EAST_EMPIRE_COMPANY || vnum2 == TES_OBJ_APPAREL_EAST_EMPIRE_COMPANY)  {prompt_guild = "for the East empire company.";}
    else if(vnum1 == TES_OBJ_APPAREL_TRIBUNAL_TEMPLE 	 || vnum2 == TES_OBJ_APPAREL_TRIBUNAL_TEMPLE)      {prompt_guild = "for the Tribunal temple.";}
    else if(vnum1 == TES_OBJ_APPAREL_MORAG_TONG 		 || vnum2 == TES_OBJ_APPAREL_MORAG_TONG)           {prompt_guild = "for the Morag tong.";}
    else if(vnum1 == TES_OBJ_APPAREL_CAMONNA_TONG 		 || vnum2 == TES_OBJ_APPAREL_CAMONNA_TONG)         {prompt_guild = "for the Camonna tong.";}
    else if(vnum1 == TES_OBJ_APPAREL_NEREVARINE_CULT 	 || vnum2 == TES_OBJ_APPAREL_NEREVARINE_CULT)      {prompt_guild = "for the Nerevarine's cult.";}
    else if(vnum1 == TES_OBJ_APPAREL_TWIN_LAMPS 		 || vnum2 == TES_OBJ_APPAREL_TWIN_LAMPS)           {prompt_guild = "for the Twin lamps.";}
    else if(vnum1 == TES_OBJ_APPAREL_HOUSE_REDORAN 		 || vnum2 == TES_OBJ_APPAREL_HOUSE_REDORAN)        {prompt_guild = "for the House Redoran.";}
    else if(vnum1 == TES_OBJ_APPAREL_HOUSE_HLAALU 		 || vnum2 == TES_OBJ_APPAREL_HOUSE_HLAALU)         {prompt_guild = "for the House Hlaalu.";}
    else if(vnum1 == TES_OBJ_APPAREL_HOUSE_TELVANNI 	 || vnum2 == TES_OBJ_APPAREL_HOUSE_TELVANNI)       {prompt_guild = "for the House Telvanni.";}
    else if(vnum1 == TES_OBJ_APPAREL_HOUSE_DRES 		 || vnum2 == TES_OBJ_APPAREL_HOUSE_DRES)           {prompt_guild = "for the House Dres.";}
    else if(vnum1 == TES_OBJ_APPAREL_HOUSE_INDORIL 		 || vnum2 == TES_OBJ_APPAREL_HOUSE_INDORIL)        {prompt_guild = "for the House Indoril.";}
    else if(vnum1 == TES_OBJ_APPAREL_HOUSE_DAGOTH 		 || vnum2 == TES_OBJ_APPAREL_HOUSE_DAGOTH)         {prompt_guild = "for the Sixth house.";}
    else if(vnum1 == TES_OBJ_APPAREL_CENSUS_AND_EXCISE 	 || vnum2 == TES_OBJ_APPAREL_CENSUS_AND_EXCISE)    {prompt_guild = "for the Census and excise.";}
    else if(vnum1 == TES_OBJ_APPAREL_ASHLANDERS 		 || vnum2 == TES_OBJ_APPAREL_ASHLANDERS)           {prompt_guild = "for the Ashlanders.";}
    else if(vnum1 == TES_OBJ_APPAREL_FACTIONLESS 		 || vnum2 == TES_OBJ_APPAREL_FACTIONLESS)          {prompt_guild = "for the Factionless.";}
    else if(vnum1 == TES_OBJ_APPAREL_IMPERIAL_KNIGHTS 	 || vnum2 == TES_OBJ_APPAREL_IMPERIAL_KNIGHTS)     {prompt_guild = "for the Imperial knights.";}
	}

	if (!IS_NPC(victim) || !xIS_SET(victim->act, ACT_PET))
	{
		char eqMSG[256];
		char wearing_lc[256], wielding_lc[256], holding_lc[256];
		int i;
		
		const char *wearing = armor_type ? armor_type : "clothing"; 
		const char *wielding = (mainhand && mainhand->description) ? mainhand->description : "nothing"; 
		const char *holding = (offhand && offhand->description) ? offhand->description : "nothing";
		const char *normal_color = "&p";
		
		snprintf(wearing_lc,  sizeof(wearing_lc),  "%s", wearing);
		snprintf(wielding_lc, sizeof(wielding_lc), "%s", wielding);
		snprintf(holding_lc,  sizeof(holding_lc),  "%s", holding);

		for(i = 0; wearing_lc[i];  i++)	wearing_lc[i]  = LOWER(wearing_lc[i]);
		for(i = 0; wielding_lc[i]; i++)	wielding_lc[i] = LOWER(wielding_lc[i]);
		for(i = 0; holding_lc[i];  i++)	holding_lc[i]  = LOWER(holding_lc[i]);

		snprintf(eqMSG, sizeof(eqMSG), "%sWears %s, wields %s, holds %s.&D", normal_color, wearing_lc, wielding_lc, holding_lc);
		act(AT_WHITE, eqMSG, ch, NULL, victim, TO_CHAR);
				
		snprintf(eqMSG, sizeof(eqMSG), "%sWorks %s&D"					   , normal_color, prompt_guild);
		act(AT_WHITE, eqMSG, ch, NULL, victim, TO_CHAR);
		
		CHAR_RECALCULATE_PERSONAL_DISPOSITION(victim, ch);
		act(AT_PURPLE, GET_PERSONAL_DISPOSITION_FEELING(victim), victim, NULL, ch, TO_VICT);
	}
}
