void CHAR_CUSTOM_PROMPT_BARS				(CHAR_DATA *ch){
	CHAR_DATA *victim, *target;
	char bars[2][21], values[2][32], buf[512];
	const char *colors[3] = {"&R", "&B", "&Y"};
	const char *names[3] = {"HLT", "MGK", "FTG"};
	int stat, side, current, maximum, blocks, i;

	if(!ch) return;

	victim = (ch->fighting) ? ch->fighting->who : NULL;

	if(victim)
	{
		snprintf(buf, sizeof(buf), "&W%-41s%s\n\r", "YOU", "ENEMY");
		send_to_char(buf, ch);
	}

	for(stat = 0; stat < 3; stat++)
	{
		for(side = 0; side < (victim ? 2 : 1); side++)
		{
			target = (side == 0) ? ch : victim;

			if(stat == 0)
			{
				current = target->hit;
				maximum = target->max_hit;
			}
			else if(stat == 1)
			{
				current = target->mana;
				maximum = target->max_mana;
			}
			else
			{
				current = target->move;
				maximum = target->max_move;
			}

			if(maximum <= 0 || current <= 0) blocks = 0;
			else if(current >= maximum)     blocks = 20;
			else                            blocks = (int)((20LL * current + maximum - 1) / maximum);

			for(i = 0; i < 20; i++)
				bars[side][i] = (i < blocks) ? 'O' : ' ';

			bars[side][20] = '\0';

			snprintf(values[side], sizeof(values[side]), "%3.3d/%3.3d", current, maximum);
		}

		if(victim)
			snprintf(buf, sizeof(buf), "%s%s : &W[%s%s&W] %s%-11s %s%s : &W[%s%s&W] %s%s&W\n\r",
				colors[stat], names[stat], colors[stat], bars[0], colors[stat], values[0],
				colors[stat], names[stat], colors[stat], bars[1], colors[stat], values[1]);
		else
			snprintf(buf, sizeof(buf), "%s%s : &W[%s%s&W] %s%s&W\n\r",
				colors[stat], names[stat], colors[stat], bars[0], colors[stat], values[0]);

		send_to_char(buf, ch);	
	}
	send_to_char("\n\r", ch);
}
int VISIBLE_STRLEN									(const char *str){

	int len = 0;

	if(!str) return 0;
	while(*str)
	{
		/* Skip SMAUG color codes such as &C, &D, &W and ^ background codes. */
		if((*str == '&' || *str == '^') && *(str + 1))
		{
			str += 2;
			continue;
		}

		len++;
		str++;
	}

	return len;
}
void SHOW_OBJECT_CATEGORY							(CHAR_DATA *ch, char **prgpstrShow, int *prgnShow, int *pitShow, OBJ_DATA **ITEMS_IN_ROOM, int nShow, const char *title, int itemtype){

	int i;
	int line_len = 0;
	int max_len = 92;
	bool first = TRUE;

	for(i = 0; i < nShow; i++)
	{
		int item_len;
		char countbuf[32];

		if(pitShow[i] != itemtype)
			continue;

		OBJ_DATA *ITEM = ITEMS_IN_ROOM[i];

		/* Length of object name */
		item_len = VISIBLE_STRLEN(prgpstrShow[i]);

		/* Add quantity length, if any */
		countbuf[0] = '\0';

		if(prgnShow[i] > 1)
		{
			snprintf(countbuf, sizeof(countbuf), " (%d)", prgnShow[i]);
			item_len += strlen(countbuf);
		}

		if(first)
		{
			ch_printf(ch, "%s ", title);
			line_len = VISIBLE_STRLEN(title) + 1;
			first = FALSE;
		}
		else
		{
			/*
			 * ", " = 2 visible characters.
			 * If next item would exceed line limit,
			 * start another category line.
			 */
			if(line_len + 2 + item_len > max_len)
			{
				send_to_char("\r\n", ch);
				ch_printf(ch, "%s ", title);

				line_len = VISIBLE_STRLEN(title) + 1;
			}
			else
			{
				send_to_char("&W,&D ", ch);
				line_len += 2;
			}
		}

		/* Rarity color */
		OBJECT_RARITY_COLOR(ch, ITEM);
		/*
		if(ITEM)
		{
			switch(ITEM->value[5])
			{
				case 2:  set_char_color(AT_GREEN , ch); break;
				case 3:  set_char_color(AT_BLUE  , ch); break;
				case 4:  set_char_color(AT_PURPLE, ch); break;
				case 5:  set_char_color(AT_YELLOW, ch); break;
				case 6:  set_char_color(AT_RED	 , ch); break;				
				default: set_char_color(AT_WHITE , ch); break;
			}
		}
		else
			set_char_color(AT_GREY, ch);
*/
		send_to_char(prgpstrShow[i], ch);
		line_len += VISIBLE_STRLEN(prgpstrShow[i]);

		if(prgnShow[i] > 1)
		{
			ch_printf(ch, " &C(%d)&D", prgnShow[i]);
			line_len += strlen(countbuf);
		}
	}

	if(!first)
		send_to_char("\r\n", ch);
}
void OBJECT_RARITY_COLOR							(CHAR_DATA *ch, OBJ_DATA *ITEM){

	if(!ITEM)
	{
		set_char_color(AT_GREY, ch);
		return;
	}

	//ch_printf(ch, "DEBUG rarity = %d\r\n", ITEM->value[5]);

	switch(ITEM->value[5])
	{
		case 2: set_char_color(AT_GREEN,  ch); break;
		case 3: set_char_color(AT_BLUE,   ch); break;
		case 4: set_char_color(AT_PURPLE, ch); break;
		case 5: set_char_color(AT_YELLOW, ch); break;
		case 6: set_char_color(AT_RED,    ch); break;
		default:set_char_color(AT_WHITE,  ch); break;
	}
}
void CHAR_FACTION_MEMBERSHIP						(CHAR_DATA *ch){

    AFFECT_DATA af;
	OBJ_DATA *insignia1 = get_eq_char(ch, WEAR_FINGER_L);
	OBJ_DATA *insignia2 = get_eq_char(ch, WEAR_FINGER_R);
	
	int vnum1 = insignia1 ? insignia1->pIndexData->vnum : 0;
	int vnum2 = insignia2 ? insignia2->pIndexData->vnum : 0;

    // 1. Clear out old faction numbers and effects first
    ch->membership_faction_FGD = 0; affect_strip(ch, tes_faction_membership_FGD);
    ch->membership_faction_TGD = 0; affect_strip(ch, tes_faction_membership_TGD);
    ch->membership_faction_MGD = 0; affect_strip(ch, tes_faction_membership_MGD);
    ch->membership_faction_DBD = 0; affect_strip(ch, tes_faction_membership_DBD);
    ch->membership_faction_IML = 0; affect_strip(ch, tes_faction_membership_IML);
    ch->membership_faction_IMC = 0; affect_strip(ch, tes_faction_membership_IMC);
    ch->membership_faction_BLD = 0; affect_strip(ch, tes_faction_membership_BLD);
    ch->membership_faction_EEC = 0; affect_strip(ch, tes_faction_membership_EEC);
    ch->membership_faction_TRT = 0; affect_strip(ch, tes_faction_membership_TRT);
    ch->membership_faction_MTG = 0; affect_strip(ch, tes_faction_membership_MTG);
    ch->membership_faction_CTG = 0; affect_strip(ch, tes_faction_membership_CTG);
    ch->membership_faction_NVC = 0; affect_strip(ch, tes_faction_membership_NVC);
    ch->membership_faction_TNL = 0; affect_strip(ch, tes_faction_membership_TNL);
    ch->membership_faction_RDN = 0; affect_strip(ch, tes_faction_membership_RDN);
    ch->membership_faction_HLU = 0; affect_strip(ch, tes_faction_membership_HLU);
    ch->membership_faction_TLV = 0; affect_strip(ch, tes_faction_membership_TLV);
    ch->membership_faction_DRS = 0; affect_strip(ch, tes_faction_membership_DRS);
    ch->membership_faction_IND = 0; affect_strip(ch, tes_faction_membership_IND);
    ch->membership_faction_SIX = 0; affect_strip(ch, tes_faction_membership_SIX);
    ch->membership_faction_CAE = 0; affect_strip(ch, tes_faction_membership_CAE);
    ch->membership_faction_ASH = 0; affect_strip(ch, tes_faction_membership_ASH);

    if (!vnum1 && !vnum2)
    {
        //bug("DEBUG: No item detected in WEAR_FINGER_L slot.");
        CHAR_RECALCULATE_FACTIONS(ch);
        return;
    }

    // 2. Set up base affect template
    memset(&af, 0, sizeof(af));
    af.duration = -1;
    af.location = APPLY_NONE;
    af.modifier = 0;
    xCLEAR_BITS(af.bitvector);

    // 3. Match in real-time
    bool matched = false;

    // Send a message showing what VNUM the item actually has
    //bug("DEBUG: Checking item VNUM1 and VNUM2: %d, %d\n", vnum1, vnum2);
	int membership_bonus = 333;
	
	if(vnum1 || vnum2)
	{
         if(vnum1 == TES_OBJ_APPAREL_FIGHTERS_GUILD 	 || vnum2 == TES_OBJ_APPAREL_FIGHTERS_GUILD)       {ch->membership_faction_FGD += membership_bonus; af.type = tes_faction_membership_FGD; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_THIEVES_GUILD 		 || vnum2 == TES_OBJ_APPAREL_THIEVES_GUILD)        {ch->membership_faction_TGD += membership_bonus; af.type = tes_faction_membership_TGD; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_MAGES_GUILD 		 || vnum2 == TES_OBJ_APPAREL_MAGES_GUILD)          {ch->membership_faction_MGD += membership_bonus; af.type = tes_faction_membership_MGD; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_DARK_BROTHERHOOD 	 || vnum2 == TES_OBJ_APPAREL_DARK_BROTHERHOOD)     {ch->membership_faction_DBD += membership_bonus; af.type = tes_faction_membership_DBD; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_IMPERIAL_LEGION 	 || vnum2 == TES_OBJ_APPAREL_IMPERIAL_LEGION)      {ch->membership_faction_IML += membership_bonus; af.type = tes_faction_membership_IML; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_IMPERIAL_CULT 		 || vnum2 == TES_OBJ_APPAREL_IMPERIAL_CULT)        {ch->membership_faction_IMC += membership_bonus; af.type = tes_faction_membership_IMC; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_BLADES 			 || vnum2 == TES_OBJ_APPAREL_BLADES)               {ch->membership_faction_BLD += membership_bonus; af.type = tes_faction_membership_BLD; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_EAST_EMPIRE_COMPANY || vnum2 == TES_OBJ_APPAREL_EAST_EMPIRE_COMPANY)  {ch->membership_faction_EEC += membership_bonus; af.type = tes_faction_membership_EEC; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_TRIBUNAL_TEMPLE 	 || vnum2 == TES_OBJ_APPAREL_TRIBUNAL_TEMPLE)      {ch->membership_faction_TRT += membership_bonus; af.type = tes_faction_membership_TRT; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_MORAG_TONG 		 || vnum2 == TES_OBJ_APPAREL_MORAG_TONG)           {ch->membership_faction_MTG += membership_bonus; af.type = tes_faction_membership_MTG; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_CAMONNA_TONG 		 || vnum2 == TES_OBJ_APPAREL_CAMONNA_TONG)         {ch->membership_faction_CTG += membership_bonus; af.type = tes_faction_membership_CTG; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_NEREVARINE_CULT 	 || vnum2 == TES_OBJ_APPAREL_NEREVARINE_CULT)      {ch->membership_faction_NVC += membership_bonus; af.type = tes_faction_membership_NVC; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_TWIN_LAMPS 		 || vnum2 == TES_OBJ_APPAREL_TWIN_LAMPS)           {ch->membership_faction_TNL += membership_bonus; af.type = tes_faction_membership_TNL; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_HOUSE_REDORAN 		 || vnum2 == TES_OBJ_APPAREL_HOUSE_REDORAN)        {ch->membership_faction_RDN += membership_bonus; af.type = tes_faction_membership_RDN; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_HOUSE_HLAALU 		 || vnum2 == TES_OBJ_APPAREL_HOUSE_HLAALU)         {ch->membership_faction_HLU += membership_bonus; af.type = tes_faction_membership_HLU; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_HOUSE_TELVANNI 	 || vnum2 == TES_OBJ_APPAREL_HOUSE_TELVANNI)       {ch->membership_faction_TLV += membership_bonus; af.type = tes_faction_membership_TLV; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_HOUSE_DRES 		 || vnum2 == TES_OBJ_APPAREL_HOUSE_DRES)           {ch->membership_faction_DRS += membership_bonus; af.type = tes_faction_membership_DRS; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_HOUSE_INDORIL 		 || vnum2 == TES_OBJ_APPAREL_HOUSE_INDORIL)        {ch->membership_faction_IND += membership_bonus; af.type = tes_faction_membership_IND; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_HOUSE_DAGOTH 		 || vnum2 == TES_OBJ_APPAREL_HOUSE_DAGOTH)         {ch->membership_faction_SIX += membership_bonus; af.type = tes_faction_membership_SIX; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_CENSUS_AND_EXCISE 	 || vnum2 == TES_OBJ_APPAREL_CENSUS_AND_EXCISE)    {ch->membership_faction_CAE += membership_bonus; af.type = tes_faction_membership_CAE; matched = true;}
    else if(vnum1 == TES_OBJ_APPAREL_ASHLANDERS 		 || vnum2 == TES_OBJ_APPAREL_ASHLANDERS)           {ch->membership_faction_ASH += membership_bonus; af.type = tes_faction_membership_ASH; matched = true;}
	}	
	
    if (matched)
    {
        affect_to_char(ch, &af);
        //bug("DEBUG: Faction matched! Bonus and affect applied.");
    }
    else
    {
        //bug("DEBUG: Item detected, but VNUM did not match any faction variables.");
    }

    CHAR_RECALCULATE_FACTIONS(ch);
}
