void DREAMWALK_INITIALIZE_COMBAT_PROFICIENCIES		(CHAR_DATA *ch){

	(void)ch;
}
#define DREAMWALK_EQUIPMENT_SKILL_DEBUG 0
static int DREAMWALK_EQUIPMENT_REQUIRED_SKILL		(OBJ_DATA *obj){
	if(!obj) return -2;

	//Weapon categories must match the mapping used in fight.c.
	if(obj->item_type == ITEM_WEAPON || obj->item_type == ITEM_MISSILE_WEAPON || obj->item_type == ITEM_PROJECTILE)
	{
		// Each numeric value identifies ONE weapon. Keep this synchronized with fight.c.
		// 1..3 are throwing weapons (Dart, Star, Knife); 39..41 are bows/crossbow.
		switch(obj->value[4])
		{
			case  1: return tes_passive_weapon_dart;                                  // DART
			case  2: return tes_passive_weapon_star;                                  // STAR
			case  3: return tes_passive_weapon_knife;                                 // KNIFE

			case  4: return tes_passive_weapon_claw;                                  // CLAW
			case  5: return tes_passive_weapon_katar;                                 // KATAR
			case  6: return tes_passive_weapon_knuckle;                               // KNUCKLE
			case  7: return tes_passive_weapon_cestus;                                // CESTUS

			case  8: return tes_passive_weapon_dirk;                                  // DIRK
			case  9: return tes_passive_weapon_dagger;                                // DAGGER

			case 10: return tes_passive_weapon_tanto;                                 // TANTO
			case 11: return tes_passive_weapon_wakizashi;                             // WAKIZASHI
			case 12: return tes_passive_weapon_shortsword;                            // SHORTSWORD
			case 13: return tes_passive_weapon_rapier;                                // RAPIER

			case 14: return tes_passive_weapon_cutlass;                               // CUTLASS
			case 15: return tes_passive_weapon_saber;                                 // SABER
			case 16: return tes_passive_weapon_falchion;                              // FALCHION
			case 17: return tes_passive_weapon_katana;                                // KATANA
			case 18: return tes_passive_weapon_longsword;                             // LONGSWORD
			case 19: return tes_passive_weapon_broadsword;                            // BROADSWORD
			case 20: return tes_passive_weapon_claymore;                              // CLAYMORE
			case 21: return tes_passive_weapon_daikatana;                             // DAIKATANA

			case 22: return tes_passive_weapon_sickle;                                // SICKLE
			case 23: return tes_passive_weapon_handaxe;                               // HANDAXE
			case 24: return tes_passive_weapon_waraxe;                                // WARAXE
			case 25: return tes_passive_weapon_pickaxe;                               // PICKAXE
			case 26: return tes_passive_weapon_battleaxe;                             // BATTLEAXE

			case 27: return tes_passive_weapon_club;                                  // CLUB
			case 28: return tes_passive_weapon_mace;                                  // MACE
			case 29: return tes_passive_weapon_flail;                                 // FLAIL
			case 30: return tes_passive_weapon_morningstar;                           // MORNINGSTAR
			case 31: return tes_passive_weapon_staff;                                 // STAFF
			case 32: return tes_passive_weapon_warhammer;                             // WARHAMMER
			case 33: return tes_passive_weapon_maul;                                  // MAUL

			case 34: return tes_passive_weapon_spear;                                 // SPEAR
			case 35: return tes_passive_weapon_glaive;                                // GLAIVE
			case 36: return tes_passive_weapon_halberd;                               // HALBERD
			case 37: return tes_passive_weapon_lance;                                 // LANCE
			case 38: return tes_passive_weapon_pike;                                  // PIKE

			case 39: return tes_passive_weapon_shortbow;                              // SHORTBOW
			case 40: return tes_passive_weapon_longbow;                               // LONGBOW
			case 41: return tes_passive_weapon_crossbow;                              // CROSSBOW
			default: return -2;	// Legacy/unclassified weapon (no proficiency check)
		}
	}

	//Only Light, Medium, Heavy armor require those proficiencies.
	//Plain clothes and armor with value[3] == 0 remain wearable.
	if(obj->item_type == ITEM_ARMOR)
	{
		switch(obj->value[3])
		{
			case 1: return tes_passive_armor_lightarmor;
			case 2: return tes_passive_armor_mediumarmor;
			case 3: return tes_passive_armor_heavyarmor;
			default:return -2;
		}
	}

	return -2;	//Jewelry, potions, tools, normal held objects, etc.
}
bool DREAMWALK_CAN_EQUIP_PROFICIENCY				(CHAR_DATA *ch, OBJ_DATA *obj, bool show_message){
	int sn;
	char buf[MAX_STRING_LENGTH];

	if(!ch || !obj) return FALSE;
	if(IS_NPC(ch) || ch == loading_char || ch == saving_char || ch == quitting_char) return TRUE;
	if(!ch->pcdata) return FALSE;

	sn = DREAMWALK_EQUIPMENT_REQUIRED_SKILL(obj);
	if(sn == -2) return TRUE;

	//Fail closed when a recognized weapon category has no registered skill.
	if(sn < 0 || sn >= num_skills || !skill_table[sn])
	{
		bug("DREAMWALK_CAN_EQUIP_PROFICIENCY: missing skill, item vnum %d, type %d, subtype %d, rarity %d", obj->pIndexData ? obj->pIndexData->vnum : -1, obj->item_type, obj->item_type == ITEM_ARMOR ? obj->value[3] : obj->value[4], obj->value[5]);
		if(show_message) act(AT_BLOOD, "&rThis item's required proficiency is not registered. Contact an administrator.&D", ch, obj, NULL, TO_CHAR);
		return FALSE;
	}

#if DREAMWALK_EQUIPMENT_SKILL_DEBUG
	//Visible debug output: enable only when testing equipment classifications.
	if(show_message)
	{
		snprintf(buf, sizeof(buf), "&z[EQUIP DEBUG] item=%d subtype=%d rarity=%d skill=%s learned=%d&D", obj->item_type, obj->item_type == ITEM_ARMOR ? obj->value[3] : obj->value[4], obj->value[5], skill_table[sn]->name, LEARNED(ch, sn));
		act(AT_PLAIN, buf, ch, obj, NULL, TO_CHAR);
	}
#endif

	//Check proficiency silently. Messages are handled by the individual weapon checks.
	if(LEARNED(ch, sn) > 0) return TRUE;

	return FALSE;
}
void DREAMWALK_ENFORCE_WORN_PROFICIENCY				(CHAR_DATA *ch, OBJ_DATA *obj){
	if(!ch || !obj || obj->carried_by != ch || obj->wear_loc == WEAR_NONE) return;
	if(IS_NPC(ch) || ch == loading_char || ch == saving_char || ch == quitting_char) return;
	if(DREAMWALK_CAN_EQUIP_PROFICIENCY(ch, obj, TRUE)) return;

	//Show bystander feedback and remove the item exactly once.
	act(AT_ACTION, "$n removes $p because $e lacks the required proficiency.", ch, obj, NULL, TO_ROOM);
	unequip_char(ch, obj);
}
