void NPC_EQUIP_ITEM_DEFAULT							(CHAR_DATA *ch, CHAR_DATA *npc){

    OBJ_DATA *item = NULL;
	int random_item;
	
    if(!npc) return;

    if (get_eq_char(npc, WEAR_BODY) == NULL)
    {
		{item = create_object(get_obj_index(TES_OBJ_ARMOR_COMMON_SHIRT),0);}						  
        if (item) {obj_to_char(item, npc); equip_char(npc, item, WEAR_BODY);}
    }
			
    if (get_eq_char(npc, WEAR_LEGS) == NULL)
    {
		{item = create_object(get_obj_index(TES_OBJ_ARMOR_COMMON_PANTS),0);} 						  
        if (item) {obj_to_char(item, npc); equip_char(npc, item, WEAR_LEGS);}
    }

    if (get_eq_char(npc, WEAR_FEET) == NULL)
    {
		{item = create_object(get_obj_index(TES_OBJ_ARMOR_COMMON_SHOES),0);}						  
        if (item) {obj_to_char(item, npc); equip_char(npc, item, WEAR_FEET);}
    }	
}
