void CREATURE_SHOW_DESCRIPTION						(CHAR_DATA *ch, CHAR_DATA *cre){
	
	char descMSG[512];
	if(!ch || !cre) return;
	ch_printf(ch, "&P%s&D\r\n", cre->name ? cre->name : "Unknown creature");	
    snprintf(descMSG, sizeof(descMSG), "%s", cre->long_descr ? cre->long_descr : ""); 	
	act(AT_PINK, descMSG, ch, NULL, cre, TO_CHAR);
}
