void CLEAN_DREAMWALK_MOBS							(ROOM_INDEX_DATA *room){
//--------------------------------------------------------------------------------------//	
    CHAR_DATA *vch;
    CHAR_DATA *vch_next;

    if (!room) return;

    //Only clean encounters inside the dedicated Dreamwalk room range.
    //A timer value is NOT an identity flag: world NPCs also start at timer 99.
    //ACT_WORLD_SPAWN distinguishes temporary encounters from placed NPCs.
    if(room->vnum < DREAMWALK_DREAM_ROOM_FIRST || room->vnum > DREAMWALK_DREAM_ROOM_LAST) return;

    for (vch = room->first_person; vch; vch = vch_next)
    {
        vch_next = vch->next_in_room; //Save link before extract_char() invalidates it.

        if (IS_NPC(vch) && xIS_SET(vch->act, ACT_WORLD_SPAWN)
            && !vch->master && !vch->fighting && !xIS_SET(vch->act, ACT_MOUNTED)
            && !IS_AFFECTED(vch, AFF_CHARM))
        {
            extract_char(vch, TRUE);
        }
    }
}
int GENERATE_RANDOM_AREA							(void){

	return number_range(DREAMWALK_DREAM_ROOM_FIRST, DREAMWALK_DREAM_ROOM_LAST);
}
bool TELEPORT_PLAYER_TO_ROOM						(CHAR_DATA *ch, int room_vnum){

	ROOM_INDEX_DATA *next_room;

    next_room = get_room_index(room_vnum);
    if (!next_room) return FALSE;

    char_from_room(ch);
    char_to_room(ch, next_room);
    next_room->light = UMAX(next_room->light, 1);
	
    return TRUE;
}
void WORLD_RANDOM_ENCOUNTER							(CHAR_DATA *ch){								//USED IN NORMAL MOVEMENT TO SPAWN ENCOUNTERS
	
	CHAR_DATA *mob;
	bool encounter_exists = FALSE;
	int chance;

	if(!ch || IS_NPC(ch) || !ch->in_room) return;

	// Prevent encounters during Dreamwalking
	if(is_affected(ch, tes_effect_dreamwalk)) return;

	// Only one random encounter per room
	for(mob = ch->in_room->first_person; mob; mob = mob->next_in_room)
	{
		if(IS_NPC(mob) && xIS_SET(mob->act, ACT_WORLD_SPAWN))
		{
			encounter_exists = TRUE;
			break;
		}
	}

	if(encounter_exists) return;

	//A single 1-100 roll gives 10% creature, 10% NPC, 80% no spawn.
	//To change these odds, update BOTH thresholds below (second is cumulative).
	chance = number_percent();

	     if(chance <= 10) DREAMWALK_EVENT400_CREATURE_REVEAL(ch, NULL);
	else if(chance <= 20) DREAMWALK_EVENT300_NPC_REVEAL(ch, NULL);
}
