#define DREAMWALK_FRAME_WIDTH 		73 //70
#define DREAMWALK_FRAME_BODY 	 	66
#define DREAMWALK_WIDE_WIDTH  		99 //Horizontal borders
#define DREAMWALK_WIDE_BODY   		95 //Vertical borders
#define DREAMWALK_SKILL_LIMIT 		64

#define CHARSHEET_VITALS_WIDTH      27
#define CHARSHEET_COMBAT_WIDTH      23
#define CHARSHEET_RESIST1_WIDTH     18
#define CHARSHEET_RESIST2_WIDTH     18
#define CHARSHEET_STAT_ROWS 		10 //Change this to add/remove lines.

void GET_CHARSHEET_STATUS							(CHAR_DATA *ch, char *char_status){	

    switch (ch->position)
    {
        case POS_DEAD:       snprintf(char_status, MAX_STRING_LENGTH, "%-10.10s", "Dead"      ); break;
        case POS_MORTAL:     snprintf(char_status, MAX_STRING_LENGTH, "%-10.10s", "Dying"     ); break;
        case POS_INCAP:      snprintf(char_status, MAX_STRING_LENGTH, "%-10.10s", "Helpless"  ); break;
        case POS_STUNNED:    snprintf(char_status, MAX_STRING_LENGTH, "%-10.10s", "Stunned"   ); break;
        case POS_SLEEPING:   snprintf(char_status, MAX_STRING_LENGTH, "%-10.10s", "Sleeping"  ); break;
        case POS_RESTING:    snprintf(char_status, MAX_STRING_LENGTH, "%-10.10s", "Resting"   ); break;
        case POS_STANDING:   snprintf(char_status, MAX_STRING_LENGTH, "%-10.10s", "Standing"  ); break;
        case POS_FIGHTING:	 snprintf(char_status, MAX_STRING_LENGTH, "%-10.10s", "Fighting"  ); break;
        case POS_EVASIVE:	 snprintf(char_status, MAX_STRING_LENGTH, "%-10.10s", "Evading"   ); break;
        case POS_DEFENSIVE:  snprintf(char_status, MAX_STRING_LENGTH, "%-10.10s", "Defending" ); break;
        case POS_AGGRESSIVE: snprintf(char_status, MAX_STRING_LENGTH, "%-10.10s", "Rushing"   ); break;
        case POS_BERSERK:	 snprintf(char_status, MAX_STRING_LENGTH, "%-10.10s", "Berserking" ); break;
        case POS_MOUNTED:	 snprintf(char_status, MAX_STRING_LENGTH, "%-10.10s", "Mounted"   ); break;
        case POS_SITTING:	 snprintf(char_status, MAX_STRING_LENGTH, "%-10.10s", "Sitting"   ); break;
        default:           snprintf(char_status, MAX_STRING_LENGTH, "%-10.10s", "Unknown"   ); break;
    }
}
void GET_CHARSHEET_STYLE							(CHAR_DATA *ch, char *char_style){

	switch (ch->style)
    {
        case STYLE_EVASIVE:    snprintf(char_style, MAX_STRING_LENGTH, "%-10.10s", "Evasive"   ); break;
        case STYLE_DEFENSIVE:  snprintf(char_style, MAX_STRING_LENGTH, "%-10.10s", "Defensive" ); break;
        case STYLE_AGGRESSIVE: snprintf(char_style, MAX_STRING_LENGTH, "%-10.10s", "Aggressive"); break;
        case STYLE_BERSERK:    snprintf(char_style, MAX_STRING_LENGTH, "%-10.10s", "Berserk"   ); break;
        default:               snprintf(char_style, MAX_STRING_LENGTH, "%-10.10s", "Standard"  ); break;
    }	
}
void GET_CHARSHEET_EFFECTS							(CHAR_DATA *ch, char effect[8][64]){

	AFFECT_DATA *paf;
	int idx = 0;

	/* Initialize all slots as "No effect" */
	for (int i = 0; i < 8; i++)
	{
		snprintf(effect[i], 64, "Nothing");
	}

	/* Fill with real effects up to 8 */
	for (paf = ch->first_affect; paf && idx < 8; paf = paf->next)
	{
		SKILLTYPE *sktmp = get_skilltype(paf->type);
		if (!sktmp)
			continue;

		if(paf->duration < 0) snprintf(effect[idx], 64, "%.20s (always)", (sktmp->name ? sktmp->name : "Effect"));
		else                  snprintf(effect[idx], 64, "%.20s (%d)", (sktmp->name ? sktmp->name : "Effect"), paf->duration);
		idx++;
	}
}
