struct DREAMWALK_CHARACTER_SKILL {
	
	const char *name;
	int value;
	int group;
};
const char *DREAMWALK_GET_SAFE_TEXT					(const char *str){
	
	return str && str[0] ? str : "Unknown";
}
const char *DREAMWALK_GET_ITEM_NAME					(OBJ_DATA *obj){
	
	return obj && obj->short_descr ? obj->short_descr : "Nothing";
}
int DREAMWALK_CALCULATE_PERCENTAGE					(int current, int maximum){

	if(maximum <= 0) return 0;
	long long percent = ((long long)current * 100 + maximum / 2) / maximum;
	if(percent < 0) return 0;
	if(percent > 100) return 100;
	return (int)percent;
}
const char *DREAMWALK_GET_PROGRESS_BAR_COLOR		(int percent){												//STATS BARS COLORS
	
	if(percent <= 25) return "&R";
	if(percent <= 60) return "&Y";
	return "&G";
}
void DREAMWALK_CREATE_PROGRESS_BAR					(char *output, int percent, int width){ 					//STATS BAR FILLING

	int i, filled;
	percent = URANGE(0, percent, 100);
	filled = (percent * width + 50) / 100;
	for(i = 0; i < width; i++) output[i] = i < filled ? '*' : ' ';
	output[width] = '\0';	
}
void DREAMWALK_PRINT_NORMAL_BORDER					(CHAR_DATA *ch, const char *name, bool heavy){ 					//TRUE = FALSE -

	char line[MAX_STRING_LENGTH];
	int i = 0, visible = 0, j = 0;
	const char *p = name ? name : "";
	char fill = heavy ? '=' : '-';

	line[i++] = '+';
	line[i++] = fill;
	line[i++] = fill;
	line[i++] = fill;
	line[i++] = '[';
	line[i++] = ' ';
	visible = 6;

	//PRINT TITLE - IGNORE SMAUG COLOR CODES IN WIDTH
	while(*p && j < 50 && visible < DREAMWALK_FRAME_WIDTH - 3 && i < MAX_STRING_LENGTH - 8)
	{
		if((*p == '&' || *p == '^') && p[1])
		{
			line[i++] = *p++;
			line[i++] = *p++;
		}
		else
		{
			line[i++] = *p++;
			visible++;
			j++;
		}
	}

	//CLOSE TITLE
	line[i++] = ' ';
	line[i++] = ']';
	visible += 2;

	//FILL BORDER TO EXACT WIDTH
	while(visible < DREAMWALK_FRAME_WIDTH - 1)
	{
		line[i++] = fill;
		visible++;
	}

	line[i++] = '+';
	line[i] = '\0';

	pager_printf(ch, "&Y%s&D\r\n", line);
}
void DREAMWALK_PRINT_NORMAL_ROW						(CHAR_DATA *ch, const char *format, ...){

	char source[MAX_STRING_LENGTH];
	char output[MAX_STRING_LENGTH];
	int i = 0, j = 0, visible = 0;
	va_list args;

	va_start(args, format);
	vsnprintf(source, sizeof(source), format, args);
	va_end(args);

	while(source[i] && visible < DREAMWALK_FRAME_BODY && j < MAX_STRING_LENGTH - 4)
	{
		if((source[i] == '&' || source[i] == '^') && source[i + 1])
		{
			output[j++] = source[i++];
			output[j++] = source[i++];
			continue;
		}
		if(source[i] == '\r' || source[i] == '\n') break;
		output[j++] = source[i++];
		visible++;
	}
	output[j] = '\0';
	pager_printf(ch, "&Y|&D %s&D%*s &Y|&D\r\n", output, DREAMWALK_FRAME_BODY - visible, "");
}
