void DREAMWALK_PRINT_WIDE_PLAIN_BORDER				(CHAR_DATA *ch, bool heavy){									//TRUE = FALSE -

	char line[DREAMWALK_WIDE_WIDTH + 1];
	int i;

	line[0] = '+';

	for(i = 1; i < DREAMWALK_WIDE_WIDTH - 1; i++)
		line[i] = heavy ? '=' : '-';

	line[i++] = '+';
	line[i] = '\0';

	pager_printf(ch, "&Y%s&D\r\n", line);
}
int DREAMWALK_COUNT_VISIBLE_CHARACTERS				(const char *str){

	int len = 0;
	if(!str) return 0;
	while(*str)
	{
		if((*str == '&' || *str == '^') && str[1]) {str += 2; continue;}
		len++;
		str++;
	}
	return len;
}
void DREAMWALK_FIT_TEXT_TO_COLUMN					(char *dest, int cap, const char *src, int width){

	int n = 0, shown = 0;
	if(!src) src = "";
	while(*src && shown < width && n < cap - 3)
	{
		if((*src == '&' || *src == '^') && src[1])
		{
			dest[n++] = *src++;
			dest[n++] = *src++;
			continue;
		}
		dest[n++] = *src++;
		shown++;
	}
	while(shown++ < width && n < cap - 1) dest[n++] = ' ';
	dest[n] = '\0';
}
