void DREAMWALK_SHOW_SCORE_FACTION					(CHAR_DATA *ch, CHAR_DATA *victim){
	
	//******************************************//
	  void CHAR_RECALCULATE_FULL(CHAR_DATA *ch);
	//******************************************//
	
	struct {const char *tag; const char *name; int value;} 
	
	factions[] =
	{
		{"FGD", "Fighters Guild"		, victim->char_faction_FGD},
		{"TGD", "Thieves Guild"			, victim->char_faction_TGD},
		{"MGD", "Mages Guild"			, victim->char_faction_MGD},
		{"DBD", "Dark Brotherhood"		, victim->char_faction_DBD},
		{"IML", "Imperial Legion"		, victim->char_faction_IML},
		{"IMC", "Imperial Cult"			, victim->char_faction_IMC},
		{"BLD", "Blades"				, victim->char_faction_BLD},
		{"EEC", "East Empire Company"	, victim->char_faction_EEC},
		{"TRT", "Tribunal Temple"		, victim->char_faction_TRT},
		{"MTG", "Morag Tong"			, victim->char_faction_MTG},
		{"CTG", "Camonna Tong"			, victim->char_faction_CTG},
		{"NVC", "Nerevarine Cult"		, victim->char_faction_NVC},
		{"TNL", "Twin Lamps"			, victim->char_faction_TNL},
		{"RDN", "House Redoran"			, victim->char_faction_RDN},
		{"HLU", "House Hlaalu"			, victim->char_faction_HLU},
		{"TLV", "House Telvanni"		, victim->char_faction_TLV},
		{"DRS", "House Dres"			, victim->char_faction_DRS},
		{"IND", "House Indoril"			, victim->char_faction_IND},
		{"SIX", "Sixth House"			, victim->char_faction_SIX},
		{"CAE", "Census and Excise"		, victim->char_faction_CAE},
		{"ASH", "Ashlanders"			, victim->char_faction_ASH},
		{"NBL", "Nobility"				, victim->char_faction_NBL},
		{"CMN", "Commoners"				, victim->char_faction_CMN},
		{"SLV", "Slaves"				, victim->char_faction_SLV}
	};

	char first[160], second[160], left[160], right[160];
	int i, count, split;

	//**********************************************************************//
	// COLUMN WIDTHS - ADJUST THESE BY HAND
	// 46 + 47 + 2 SPACES = 95 VISIBLE CHARACTERS
	//**********************************************************************//
	const int width1 = 46;
	const int width2 = 47;

	count = sizeof(factions) / sizeof(factions[0]);
	split = (count + 1) / 2;

	//************************************************************************//
    DREAMWALK_PRINT_WIDE_BORDER(ch, "&RF A C T I O N   S T A N D I N G S&Y", TRUE);
	//************************************************************************//

	DREAMWALK_PRINT_WIDE_ROW(ch, "");
	
	DREAMWALK_PRINT_WIDE_BORDER(ch, "KNOWN FACTIONS", FALSE);
	
	//**********************************************************************//
	// FACTION LIST - TWO COLUMNS
	//**********************************************************************//

	for(i = 0; i < split; i++)
	{
		//LEFT COLUMN
		snprintf(first, sizeof(first), "&C%-3.3s &W%-21.21s  &Y%+5d &W%s",
			factions[i].tag,
			factions[i].name,
			factions[i].value,
			GET_RELATION((short)URANGE(-999, factions[i].value, 999)));

		//RIGHT COLUMN
		second[0] = '\0';

		if(i + split < count)
		{
			snprintf(second, sizeof(second), "&C%-3.3s &W%-21.21s  &Y%+5d &W%s",
				factions[i + split].tag,
				factions[i + split].name,
				factions[i + split].value,
				GET_RELATION((short)URANGE(-999, factions[i + split].value, 999)));
		}

		DREAMWALK_FIT_TEXT_TO_COLUMN(left,  sizeof(left),  first,  width1);
		DREAMWALK_FIT_TEXT_TO_COLUMN(right, sizeof(right), second, width2);

		// CHANGE THE SPACES HERE TO ADJUST THE GAP
		DREAMWALK_PRINT_WIDE_ROW(ch, "%s  %s", left, right);
	}

	DREAMWALK_PRINT_WIDE_PLAIN_BORDER(ch, TRUE);
}
