void MANUAL_SKILL_SHARPEN_WEAPON					(CHAR_DATA *ch, const char *argument){
	char cMSG[256], vMSG[256], rMSG[256];
	char buf[MAX_STRING_LENGTH];
	char arg1[MAX_INPUT_LENGTH]; one_argument(argument, arg1);
	OBJ_DATA *whetstone = get_obj_carry(ch, "whetstone");
	OBJ_DATA *weapon = get_obj_carry(ch, arg1);
	int dice  = number_range(1,100);
	int check = (LEARNED(ch, tes_skill_sharpen_weapon)/2 + get_curr_str(ch));
	int cost  = 10;
	
	if(check < 5) check = 5; if(check > 95) check = 95;
	
	if(arg1[0] == '\0') 												 {act(AT_YELLOW, "Sharpen what?"						   	, ch, NULL, NULL, TO_CHAR); return;}
	if(!(weapon))                              							 {act(AT_YELLOW, "You need to have this item in inventory."	, ch, NULL, NULL, TO_CHAR); return;}
	if(weapon->item_type != ITEM_WEAPON)                                 {act(AT_YELLOW, "You can sharpen only weapons."			, ch, NULL, NULL, TO_CHAR); return;}
	if(ch->move < cost)                                                  {act(AT_YELLOW, "You don't have enough fatigue."			, ch, NULL, NULL, TO_CHAR); return;}
	if(IS_NPC(ch) && IS_AFFECTED(ch, AFF_CHARM))                         {act(AT_YELLOW, "You can't concentrate enough for that."	, ch, NULL, NULL, TO_CHAR); return;}
	if(weapon->value[1] == 5 || (weapon->value[1] == weapon->value[2]))  {act(AT_YELLOW, "You can't sharpen it anymore."			, ch, NULL, NULL, TO_CHAR); return;}
	if(weapon->value[0] == 0)                                            {act(AT_YELLOW, "You have broken the weapon."			    , ch, NULL, NULL, TO_CHAR); return;}
	if(whetstone == NULL)                                                {act(AT_YELLOW, "You need a whetstone."					, ch, NULL, NULL, TO_CHAR); return;}

	sprintf(cMSG, "You are trying to sharpen the weapon for extra damage."); act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
	sprintf(cMSG, "You have %d%% chance.", check); 					  	 	 act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
	sprintf(rMSG, "$n is sharpening a weapon."); 	 					 	 act(AT_PINK, rMSG, ch, NULL, NULL, TO_NOTVICT);
	
	if(dice < check)
	{
		sprintf(cMSG, "Result: &GSuccess&D"); 			     act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
		snprintf(cMSG, sizeof(cMSG), "You sharpen the %s.\r\n", weapon->name); act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);

		snprintf(buf, MAX_STRING_LENGTH, "sharpened %s", weapon->pIndexData->name); STRFREE(weapon->name); weapon->name = STRALLOC(buf);
		snprintf(buf, MAX_STRING_LENGTH, "sharpened %s", weapon->pIndexData->name); STRFREE(weapon->short_descr); weapon->short_descr = STRALLOC(buf);
		snprintf(buf, MAX_STRING_LENGTH, "Sharpened %s", weapon->pIndexData->name); STRFREE(weapon->description); weapon->description = STRALLOC(buf);	
		weapon->value[1] = weapon->value[1] + 1;
		if(weapon->value[1] >= weapon->value[2])
		learn_from_success(ch, tes_skill_sharpen_weapon);
	}
	else
	{
		sprintf(cMSG, "Result: &RFailure&D"); 			    act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
		snprintf(cMSG, sizeof(cMSG), "You damage the %s.\r\n", weapon->name); act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
		weapon->value[0] = weapon->value[1] - 1; 
		if(weapon->value[0] < 0) weapon->value[0] = 0;
	}
	separate_obj(whetstone); extract_obj(whetstone);
	ch->move = ch->move - cost;
	return;
}
void MANUAL_SKILL_REINFORCE_ARMOR					(CHAR_DATA *ch, const char *argument){
	char cMSG[256], vMSG[256], rMSG[256];
	char arg[MAX_INPUT_LENGTH]; one_argument(argument, arg);
	char bufname[MAX_INPUT_LENGTH]; char descbuf[MAX_STRING_LENGTH];
	OBJ_DATA *armor 	= get_obj_carry(ch, arg);
	OBJ_DATA *titanium 	= get_obj_carry(ch, "titanium");
	int dice 			= number_range(1,100);
	int check 			= (LEARNED(ch, tes_skill_reinforce_armor)/2 + get_curr_con(ch));
	int cost 			= 10;

	if(arg[0] == '\0')                           {act(AT_YELLOW, "Reinforce what?"						 	, ch, NULL, NULL, TO_CHAR); return;}
	if(armor == NULL)                            {act(AT_YELLOW, "You need to have this item in inventory."	, ch, NULL, NULL, TO_CHAR); return;}
	if(armor->item_type != ITEM_ARMOR)           {act(AT_YELLOW, "You can reinforce only armor."			, ch, NULL, NULL, TO_CHAR); return;}
	if(ch->move < cost)                          {act(AT_YELLOW, "You don't have enough fatigue."		    , ch, NULL, NULL, TO_CHAR); return;}
	if(IS_NPC(ch) && IS_AFFECTED(ch, AFF_CHARM)) {act(AT_YELLOW, "You can't concentrate enough for that."	, ch, NULL, NULL, TO_CHAR); return;}
	if(armor->value[0] == 0)                     {act(AT_YELLOW, "You have broken the armor."				, ch, NULL, NULL, TO_CHAR); return;}
	if(titanium == NULL)                         {act(AT_YELLOW, "You need a titanium plate."				, ch, NULL, NULL, TO_CHAR); return;}
	if(IS_OBJ_STAT(armor, ITEM_ENCHANTED))       {act(AT_YELLOW, "You can't reinforce this armor more."	 	, ch, NULL, NULL, TO_CHAR); return;}

	sprintf(cMSG, "You are trying to reinforce the armor piece for extra defence."); act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
	sprintf(cMSG, "You have %d%% chance.", check);  				     			 act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
	sprintf(rMSG, "$n is reinforcing an armor piece."); 	 	 				   	 act(AT_PINK, rMSG, ch, NULL, NULL, TO_NOTVICT);

	if(dice < check)
	{
		sprintf(cMSG, "Result: &GSuccess&D"); 			     act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
		sprintf(cMSG, "You reinforce the %s.", armor->name); act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);

		snprintf(bufname, MAX_STRING_LENGTH, "reinforced %s",  armor->pIndexData->name); STRFREE(armor->name); armor->name = STRALLOC(bufname);
		snprintf(bufname, MAX_STRING_LENGTH, "reinforced %s",  armor->pIndexData->name); STRFREE(armor->short_descr); armor->short_descr = STRALLOC(bufname);
		snprintf(descbuf, MAX_STRING_LENGTH, "Reinforced %s.", armor->pIndexData->name); STRFREE(armor->description); armor->description = STRALLOC(descbuf);

	armor->value[0] += 10; if(armor->value[0] > 100) armor->value[0] = 100;
	armor->value[1] += 10; if(armor->value[1] > 100) armor->value[1] = 100;
	
		xSET_BIT(armor->extra_flags, ITEM_ENCHANTED);	
		learn_from_success(ch, tes_skill_reinforce_armor);
	}
	else
	{
		sprintf(cMSG, "Result: &RFailure&D");   		  act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
		sprintf(cMSG, "You damage the %s.", armor->name); act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
		armor->value[0] -= 1;
	}
	separate_obj(titanium); extract_obj(titanium);
	ch->move = ch->move - cost;
	return;
}
void MANUAL_SKILL_REPAIR_ITEM						(CHAR_DATA *ch, const char *argument){
	char cMSG[256], vMSG[256], rMSG[256];	
	char arg[MAX_INPUT_LENGTH]; one_argument(argument, arg);
	OBJ_DATA *obj = get_obj_carry(ch, arg);
	OBJ_DATA *hammer = get_obj_carry(ch, "hammer");
	int dice  = number_range(1,100);
	int check = (LEARNED(ch, tes_skill_repair_item)/2) + get_curr_str(ch);
	int cost  = 10;

	if(check < 5) check = 5; if(check > 95) check = 95;
	
	if(ch->fighting) 							 						{act(AT_YELLOW, "You can't do that in combat."		  	, ch, NULL, NULL, TO_CHAR); return;}
	if(IS_NPC(ch) && IS_AFFECTED(ch, AFF_CHARM)) 						{act(AT_YELLOW, "You can't concentrate enough for that.", ch, NULL, NULL, TO_CHAR); return;}
	if(ch->mount) 								 						{act(AT_YELLOW, "You can't do that while mounted."	  	, ch, NULL, NULL, TO_CHAR); return;}
	if(ch->move < cost)							 						{act(AT_YELLOW, "You don't have enough fatigue."		, ch, NULL, NULL, TO_CHAR); return;}
	if(arg[0] == '\0')							 						{act(AT_YELLOW, "Repair what?"				 		  	, ch, NULL, NULL, TO_CHAR); return;}
	if(obj == NULL)								 						{act(AT_YELLOW, "You don't have this item."			  	, ch, NULL, NULL, TO_CHAR); return;}
	if(hammer == NULL)							 						{act(AT_YELLOW, "You need a hammer."				 	, ch, NULL, NULL, TO_CHAR); return;}
	if(obj->item_type != ITEM_WEAPON && obj->item_type != ITEM_ARMOR) 	{act(AT_YELLOW, "You may repair only weapons and armor.", ch, NULL, NULL, TO_CHAR); return;}
	if(obj->item_type == ITEM_WEAPON && obj->value[0] == 13) 		    {act(AT_YELLOW, "You don't need to repair that."		, ch, NULL, NULL, TO_CHAR); return;}
	if(obj->item_type == ITEM_ARMOR  && obj->value[0] == obj->value[1]) {act(AT_YELLOW, "You don't need to repair that."		, ch, NULL, NULL, TO_CHAR); return;}

	sprintf(cMSG, "You are trying to repair the item."); act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
	sprintf(cMSG, "You have %d%% chance.", check);       act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
	sprintf(rMSG, "$n is trying to repair an item."); 	 act(AT_PINK, rMSG, ch, NULL, NULL, TO_NOTVICT);
	
	if(dice < check)
	{
		sprintf(cMSG, "Result: &GSuccess&D"); act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
		obj->value[0] = obj->value[0] + 1;   
		learn_from_success(ch, tes_skill_repair_item);
		if(obj->item_type == ITEM_WEAPON) {if(obj->value[0] > 13) {obj->value[0] = 13;}}
		if(obj->item_type == ITEM_ARMOR)  {if(obj->value[0] > obj->value[1]) {obj->value[0] = obj->value[1];}}		
	}
	else
	{sprintf(cMSG, "Result: &RFailure&D"); act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);}

	separate_obj(hammer); extract_obj(hammer);
	ch->move = ch->move - cost;
	return;
}
