void MANUAL_SKILL_SEARCH_SOMETHING					(CHAR_DATA *ch, const char *argument){
    char cMSG[256], vMSG[256], rMSG[256];
    char arg[MAX_INPUT_LENGTH]; argument = one_argument(argument, arg);
    OBJ_DATA *obj;
    OBJ_DATA *container = get_obj_here(ch, arg);
    OBJ_DATA *startobj;
    int door = -1;
    int dice = number_range(1,100);
    int check = (LEARNED(ch, tes_skill_search_something)/2) + get_curr_int(ch); 
    int cost = 10;

	if(check < 5) check = 5; if(check > 95) check = 95;
	
    switch (ch->substate)
    {
        default:
        if(IS_NPC(ch) && IS_AFFECTED(ch, AFF_CHARM))    {act(AT_YELLOW, "You can't concentrate enough for that.", ch, NULL, NULL, TO_CHAR); return;}
        if(ch->mount)                                   {act(AT_YELLOW, "You can't do that while mounted."		, ch, NULL, NULL, TO_CHAR); return;}
        if(ch->move < cost)                             {act(AT_YELLOW, "You don't have enough fatigue."		, ch, NULL, NULL, TO_CHAR); return;}
        
        if(arg[0] != '\0' && (door = get_door(arg)) == -1) 
        {
            if(!container)                              {act(AT_YELLOW, "You can't find that here.", ch, NULL, NULL, TO_CHAR); return;}
            if(container->item_type != ITEM_CONTAINER)  {act(AT_YELLOW, "You can't search in that!", ch, NULL, NULL, TO_CHAR); return;}
            if(IS_SET(container->value[1], CONT_CLOSED)){act(AT_YELLOW, "It is closed."			   , ch, NULL, NULL, TO_CHAR); return;}
        }    
    }

    ch->substate = SUB_NONE;

    if(arg[0] == '\0') 
        startobj = ch->in_room->first_content;
    else
    {
        if((door = get_door(arg)) != -1)
            startobj = NULL;
        else
        {
            if(!container) 
				{act(AT_YELLOW, "You can't find that here.", ch, NULL, NULL, TO_CHAR); return;}
				startobj = container->first_content;
        }
    }

    sprintf(cMSG, "You are trying to search for hidden items."); act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
    sprintf(cMSG, "You have %d%% chance.", check);			 	 act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
	sprintf(rMSG, "$n is searching around."); 	 				 act(AT_PINK, rMSG, ch, NULL, NULL, TO_NOTVICT);
	
    if(dice > check)
    {
        sprintf(cMSG, "Result: &RFailure&D"); act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
    }
    else
    {
        if(door != -1)
        {
            EXIT_DATA *pexit;

            if((pexit = get_exit(ch->in_room, door)) != NULL && IS_SET(pexit->exit_info, EX_SECRET) && IS_SET(pexit->exit_info, EX_xSEARCHABLE))
            {
                sprintf(cMSG, "Result: &GSuccess&D"); act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
                sprintf(rMSG, "You find the $d.");    act(AT_YELLOW, rMSG, ch, NULL, pexit->keyword, TO_CHAR);
                sprintf(rMSG, "$n finds the $d.");    act(AT_YELLOW, rMSG, ch, NULL, pexit->keyword, TO_NOTVICT);
                REMOVE_BIT(pexit->exit_info, EX_SECRET);
                learn_from_success(ch, tes_skill_search_something);
            }
        }
        else
        {
            for(obj = startobj; obj; obj = obj->next_content)
            {
                if(number_percent() < check && IS_OBJ_STAT(obj, ITEM_HIDDEN))
                {
                    separate_obj(obj);
                    xREMOVE_BIT(obj->extra_flags, ITEM_HIDDEN);
                    sprintf(cMSG, "Result: &GSuccess&D"); act(AT_SKILL, cMSG, ch, NULL, NULL, TO_CHAR);
                    sprintf(rMSG, "You find the $p.");    act(AT_SKILL, rMSG, ch, obj, NULL, TO_CHAR);
                    sprintf(rMSG, "$n finds the $p.");    act(AT_SKILL, rMSG, ch, obj, NULL, TO_NOTVICT);
                    learn_from_success(ch, tes_skill_search_something);
                }
            }
        }    
    }
    ch->move = ch->move - cost;
    return;
}
