void MANUAL_SKILL_REMOVE_TRAP						(CHAR_DATA *ch, const char *argument){
   char arg[MAX_INPUT_LENGTH];
   OBJ_DATA *obj; OBJ_DATA *trap;
   int percent; bool found = FALSE;

	switch ( ch->substate )
    {
		default:

		if(IS_NPC(ch) && IS_AFFECTED(ch, AFF_CHARM))     {act(AT_YELLOW, "You can't concentrate enough for that.", ch, NULL, NULL, TO_CHAR); return;}
		argument = one_argument( argument, arg ); 
		if(!can_use_skill(ch, 0, tes_skill_remove_trap)) {act(AT_YELLOW, "You do not yet know of this skill."	 , ch, NULL, NULL, TO_CHAR); return;}
		if(arg[0] == '\0')							 	 {act(AT_YELLOW, "Detrap what?"							 , ch, NULL, NULL, TO_CHAR); return;}
		if(ms_find_obj(ch))																													 return;
        found = FALSE;
        if(ch->mount)								 	 {act(AT_YELLOW, "You can't do that while mounted."		 , ch, NULL, NULL, TO_CHAR); return;}
        if(!ch->in_room->first_content)			 	     {act(AT_YELLOW, "You can't find that here."			 , ch, NULL, NULL, TO_CHAR); return;}

        for( obj = ch->in_room->first_content; obj; obj = obj->next_content )
        {
            if( can_see_obj( ch, obj ) && nifty_is_name( arg, obj->name ) )
            {
				found = TRUE;
				break;
            }
        }

        if(!found) 
			{act(AT_YELLOW, "You can't find that here.", ch, NULL, NULL, TO_CHAR); return;}

        act(AT_YELLOW, "You carefully begin your attempt to remove a trap from $p...", ch, obj, NULL, TO_CHAR);
        act(AT_YELLOW, "$n carefully attempts to remove a trap from $p...", ch, obj, NULL, TO_ROOM);
        ch->alloc_ptr = str_dup( obj->name);
        add_timer(ch, TIMER_DO_FUN, 3, MANUAL_SKILL_REMOVE_TRAP, 1);
		/*WAIT_STATE( ch, skill_table[tes_skill_remove_trap]->beats );*/
        return;

		case 1:
			if(!ch->alloc_ptr)
			{
				act(AT_YELLOW, "Your detrapping was interrupted!", ch, NULL, NULL, TO_CHAR);
				bug("%s", "do_detrap: ch->alloc_ptr NULL!");
				return;
			}
			mudstrlcpy(arg, ch->alloc_ptr, MAX_INPUT_LENGTH);
			DISPOSE( ch->alloc_ptr );
			ch->alloc_ptr = NULL;
			ch->substate = SUB_NONE;
			break;

		case SUB_TIMER_DO_ABORT:
			DISPOSE(ch->alloc_ptr);
			ch->substate = SUB_NONE;
			act(AT_YELLOW, "You carefully stop what you were doing.", ch, NULL, NULL, TO_CHAR);			
			return;
	}

	if(!ch->in_room->first_content) 
		{act(AT_YELLOW, "You can't find that here.", ch, NULL, NULL, TO_CHAR); return;} 

	for(obj = ch->in_room->first_content; obj; obj = obj->next_content)
	{
		if(can_see_obj(ch, obj) && nifty_is_name(arg, obj->name))
		{
			found = TRUE;
			break;
		}
	}

	if(!found) 						   {act(AT_YELLOW, "You can't find that here.", ch, NULL, NULL, TO_CHAR); return;}
	if((trap = get_trap(obj)) == NULL) {act(AT_YELLOW, "You find no trap on that.", ch, NULL, NULL, TO_CHAR); return;}

	percent = number_percent() - (ch->level /15) - (get_curr_lck(ch) -16);

	separate_obj(obj);
	if( !can_use_skill(ch, percent, tes_skill_remove_trap))
	{
		act(AT_YELLOW, "Ooops!", ch, NULL, NULL, TO_CHAR);
		spring_trap(ch, trap);
		return;
	}

	extract_obj(trap);
	act(AT_YELLOW, "You successfully remove a trap.", ch, NULL, NULL, TO_CHAR);
	learn_from_success(ch, tes_skill_remove_trap);
	return;
}
void MANUAL_SKILL_PEEK_INVENTORY					(CHAR_DATA *ch, const char *argument){
	char cMSG[256], vMSG[256], rMSG[256];
	char arg[MAX_INPUT_LENGTH];
	argument 		  = one_argument(argument, arg);
	CHAR_DATA *victim = get_char_room(ch, arg);
	int dice 		  = number_percent();
	int check 		  = (LEARNED(ch, tes_skill_peek_inventory)/2 + get_curr_int(ch));
	int cost 		  = 10;

	if(check < 5) check = 5; if(check > 95) check = 95;
	
	
	if(arg[0] == '\0') 							 {act(AT_YELLOW, "Peek on whom?"		   				   , ch, NULL, NULL, TO_CHAR); return;}
	if(IS_NPC(ch) && IS_AFFECTED(ch, AFF_CHARM)) {act(AT_YELLOW, "You can't concentrate enough for that."  , ch, NULL, NULL, TO_CHAR); return;}
	if(victim == ch)							 {act(AT_YELLOW, "Oh you think you can do that?"		   , ch, NULL, NULL, TO_CHAR); return;}
	if(victim == NULL)							 {act(AT_YELLOW, "They aren't here."		   			   , ch, NULL, NULL, TO_CHAR); return;}
	const char *pronoun = "their"; if(victim->sex == 1) pronoun = "his"; else if(victim->sex == 2) pronoun = "her";	
	if(ch->move < cost)							 {act(AT_YELLOW, "You don't have enough fatigue."		   , ch, NULL, NULL, TO_CHAR); return;}

    sprintf(cMSG, "You are trying to peek at %s inventory:", pronoun); act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
	sprintf(cMSG, "You have %d%% chance.", check); 			       	   act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
	sprintf(rMSG, "$n is looking at $N's possessions.");			   act(AT_PINK, rMSG, ch, NULL, victim, TO_NOTVICT);
	
	if(dice > check)
    {
		sprintf(cMSG, "Result: &RFailure&D"); act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
		do_say(victim, "How rude!!!");
		ch->alignment = ch->alignment - 10;
    }
	else
    {
		sprintf(cMSG, "Result: &GSuccess&D"); 							   act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
		sprintf(cMSG, "You are trying to peek at %s inventory:", pronoun); act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
		show_list_to_char(victim->first_carrying, ch, TRUE, TRUE);
		learn_from_success(ch, tes_skill_peek_inventory);
    }
	ch->move = ch->move - cost;
	return;
}
void MANUAL_SKILL_THROW_POISON						(CHAR_DATA *ch, const char *argument){
	char cMSG[256], vMSG[256], rMSG[256];
	char arg1[MAX_INPUT_LENGTH]; argument = one_argument(argument, arg1);
	char arg2[MAX_INPUT_LENGTH]; argument = one_argument(argument, arg2);
	CHAR_DATA *victim = get_char_room(ch, arg1);
	OBJ_DATA *obj 	  = get_obj_carry(ch, arg2);

	if(arg1[0] == '\0') 			  {act(AT_YELLOW, "To whom?"					  , ch, NULL, NULL, TO_CHAR); return;}
	if(arg2[0] == '\0')				  {act(AT_YELLOW, "With what?"				      , ch, NULL, NULL, TO_CHAR); return;}
	if(victim == NULL)  			  {act(AT_YELLOW, "They aren't here."			  , ch, NULL, NULL, TO_CHAR); return;}
	if(obj == NULL) 				  {act(AT_YELLOW, "You don't have this poison."   , ch, NULL, NULL, TO_CHAR); return;}
	if(obj->item_type != ITEM_POTION) {act(AT_YELLOW, "Try a poison flask."		      , ch, NULL, NULL, TO_CHAR); return;}
	if(obj->value[5] == 1)			  {act(AT_YELLOW, "This is not a throwing poison.", ch, NULL, NULL, TO_CHAR); return;}

	if(obj->value[5] == 2)
    {
		snprintf(cMSG, 256, "You throw a %s on $N.\r\n",    obj->name); act(AT_YELLOW, cMSG, ch, NULL, victim, TO_CHAR);
		snprintf(vMSG, 256, "$n&W throws a %s on you.\r\n", obj->name); act(AT_PINK, vMSG, ch, NULL, victim, TO_VICT);
		snprintf(rMSG, 256, "$n&W throws a %s on $N.\r\n" , obj->name); act(AT_PINK, rMSG, ch, NULL, victim, TO_NOTVICT);

		obj_cast_spell(obj->value[1], obj->value[0], ch, victim, obj);
		extract_obj(obj);
		learn_from_success(ch, tes_skill_throw_poison);
    }
}
void MANUAL_SKILL_BACKSTAB_CREATURE					(CHAR_DATA *ch, const char *argument){
	char cMSG[256], vMSG[256], rMSG[256];
	char arg[MAX_INPUT_LENGTH]; one_argument(argument, arg);
	CHAR_DATA *victim = get_char_room(ch, arg);
	OBJ_DATA *obj = get_eq_char(ch, WEAR_WIELD);
	int dice  = number_range(1,100);
	int check = (LEARNED(ch, tes_skill_backstab_creature)/2) + get_curr_dex(ch);
	int cost  = 10;
	
	if(check < 5) check = 5; if(check > 95) check = 95;
	
	if(IS_NPC(ch) && IS_AFFECTED(ch, AFF_CHARM)) 					 {act(AT_YELLOW, "You can't do that right now."				   , ch, NULL, NULL, TO_CHAR); return;}
	if(ch->mount)								 					 {act(AT_YELLOW, "You can't backstab while mounted."		   , ch, NULL, NULL, TO_CHAR); return;}
	if(arg[0] == '\0')							 					 {act(AT_YELLOW, "Backstab whom?"							   , ch, NULL, NULL, TO_CHAR); return;}
	if(victim == NULL) 					 						 	 {act(AT_YELLOW, "They aren't here."						   , ch, NULL, NULL, TO_CHAR); return;}
	if(victim == ch)							 					 {act(AT_YELLOW, "How can you backstab yourself?"			   , ch, NULL, NULL, TO_CHAR); return;}
	if(!IS_NPC(ch) && !IS_NPC(victim) && xIS_SET(ch->act, PLR_NICE)) {act(AT_YELLOW, "You are too nice to do that."				   , ch, NULL, NULL, TO_CHAR); return;}
	if(obj == NULL || obj->value[3] != 12) 						 	 {act(AT_YELLOW, "You need to wield a dagger."				   , ch, NULL, NULL, TO_CHAR); return;}
	if(victim->fighting)											 {act(AT_YELLOW, "You can't backstab someone who is in combat.", ch, NULL, NULL, TO_CHAR); return;}
	if(victim->hit < victim->max_hit && IS_AWAKE(victim))			 {act(AT_YELLOW, "Target is hurt and suspicious for that."	   , ch, NULL, NULL, TO_CHAR); return;}
	if(!IS_AFFECTED(ch, AFF_SNEAK))									 {act(AT_YELLOW, "You need to sneak first."				       , ch, NULL, NULL, TO_CHAR); return;}
	if(ch->move < cost) 											 {act(AT_YELLOW, "You don't have enough fatigue."			   , ch, NULL, NULL, TO_CHAR); return;}
	if(is_safe(ch, victim, TRUE)) {return;}
	
	check_attacker(ch, victim);
	WAIT_STATE(ch, skill_table[tes_skill_backstab_creature]->beats);

	sprintf(cMSG, "You are trying to backstab $N."); act(AT_YELLOW, cMSG, ch, NULL, victim, TO_CHAR);
	sprintf(cMSG, "You have %d%% chance.&D", check); act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
	sprintf(rMSG, "$n is trying to backstab $N.");   act(AT_PINK, rMSG, ch, NULL, victim, TO_NOTVICT);
	
	if(!IS_AWAKE(victim) || dice < check)
	{
		sprintf(cMSG, "Result: &GSuccess&D"); 	 act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
		global_retcode = multi_hit(ch, victim, tes_skill_backstab_creature);
		check_illegal_pk(ch, victim);
		learn_from_success(ch, tes_skill_backstab_creature);
	}
	else 
	{
		sprintf(cMSG, "Result: &RFailure&D"); act(AT_YELLOW, cMSG, ch, NULL, NULL, TO_CHAR);
		global_retcode = damage(ch, victim, 0, tes_skill_backstab_creature);
		check_illegal_pk(ch, victim);
	}
	ch->move = ch->move - cost;
	ch->alignment = ch->alignment - 10;
	return;
}
