	if (dice > check) 			  return FALSE;

	//SPECIAL CONDITION: MUST BE IMPERIAL.
	if (!IS_NPC(ch) && ch->race != 6)  return FALSE;
	if (IS_NPC(ch)  && ch->race != 96) return FALSE;

