bool AUTOMATIC_SPELL_DAMAGE_FIRE					(CHAR_DATA *ch, CHAR_DATA *victim){
//--------------------------------------------------------------------------------------------------//
	ch->number_effects 	= 1;
	RESET_EFFECT_VARIABLES(ch);
	ch->af1_name 		= "fire damage";
	ch->af1_effect 		= "damaging %s health with fire"; 
	ch->af1_skill 		= "destruction"; 
	ch->af1_resistance 	= "fire";
	ch->af1_type 		= tes_effect_damage_fire; 
	ch->af1_mmin 		= 10; 
	ch->af1_mmax 		= 20; 
	ch->af1_cost 		= 15;
	return EFFECT_TYPE_AUTOMATIC_ELEMENTAL_DAMAGE (tes_effect_damage_fire, ch, victim);
}
