//--------------------------------------------------------------------------------------------------//	
	ch->number_effects 	= 1;
	RESET_EFFECT_VARIABLES(ch);
	ch->af1_name 		= "fire shield";
	ch->af1_effect 		= "shielding %s body from fire"; 
