bool AUTOMATIC_ACTION_EXECUTE                       (CHAR_DATA *ch, CHAR_DATA *victim){
//--------------------------------------------------------------------------------------------------//

	if(!ch || !victim) return FALSE;
	if(!IS_CLASSTYPE_COMBAT_EXPERT(ch)) return FALSE;
	if(victim->max_hit <= 0 || victim->hit > victim->max_hit / 4) return FALSE;

	ch->number_effects = 1;
	RESET_EFFECT_VARIABLES(ch);

	ch->af1_name        = "Execute";
	ch->af1_effect      = "damaging %s health with a finishing blow";
	ch->af1_skill       = "hand weapon";
	ch->af1_target      = "victim";
	ch->af1_type        = tes_action_execute;
	ch->af1_location    = APPLY_HIT;
	ch->af1_mmin        = -50;
	ch->af1_mmax        = -30;
	ch->af1_cost        = 10;

	if(!DO_GENERIC_CHECKS_C(ch)) return FALSE;
	if(ch->move < ch->af1_cost) return FALSE;
	int skill = IS_NPC(ch) ? ch->char_handtohand : LEARNED(ch, tes_action_execute);
	if(skill < (IS_NPC(ch) ? 40 : 1) || number_range(1,100) > UMIN(skill,95)) return FALSE;
	if(IS_SET(victim->immune, RIS_NONMAGIC))
	{
		act(AT_YELLOW, "$N is immune to physical effects.", ch, NULL, victim, TO_CHAR);
		return FALSE;
	}
	int bonus = get_curr_str(ch) / 5;
	int effect = number_range(-ch->af1_mmax, -ch->af1_mmin) + bonus;
	if(IS_SET(victim->resistant, RIS_NONMAGIC)) effect = UMAX(1, effect / 2);
	if(IS_SET(victim->susceptible, RIS_NONMAGIC)) effect = effect + effect / 2;
	{
		char cMSG[256], vMSG[256], rMSG[256];
		char cEffect[128], vEffect[128], rEffect[128];
		ACTION_EFFECT_TEXT(cEffect, sizeof(cEffect), ch->af1_effect, "$N's");
		ACTION_EFFECT_TEXT(vEffect, sizeof(vEffect), ch->af1_effect, "your");
		ACTION_EFFECT_TEXT(rEffect, sizeof(rEffect), ch->af1_effect, "$N's");
		snprintf(cMSG, sizeof(cMSG), "You perform %s, %s by %d points.", ch->af1_name, cEffect, effect);
		snprintf(vMSG, sizeof(vMSG), "$n performs %s, %s by %d points.", ch->af1_name, vEffect, effect);
		snprintf(rMSG, sizeof(rMSG), "$n performs %s, %s by %d points.", ch->af1_name, rEffect, effect);
		act(AT_PURPLE, cMSG, ch, NULL, victim, TO_CHAR);
		act(AT_PURPLE, vMSG, ch, NULL, victim, TO_VICT);
		act(AT_PURPLE, rMSG, ch, NULL, victim, TO_NOTVICT);
	}
	global_retcode = damage(ch, victim, effect, tes_effect_damage_weapon);
	if(char_died(ch)) return FALSE;
	ch->move = UMAX(0, ch->move - ch->af1_cost);
	learn_from_success(ch, tes_action_execute);
	return TRUE;
}
