	if(ch->mana < total_magicka)
		{act(AT_YELLOW, "You dont have enough magicka.", ch, NULL, victim, TO_CHAR); return;}  


	if(is_affected(ch, tes_effect_silence))
		{snprintf(cMSG, sizeof(cMSG), "You are silenced."); act(AT_YELLOW, cMSG, ch, NULL, victim, TO_CHAR); return;}
	
	#undef CONJURE_ITEM
	#define CONJURE_ITEM(var)                                                                                                       		\
