					 if(item_type == 1) {item = create_object(get_obj_index(TES_OBJ_WEAPON_DREMORA_RAPIER    ), 0);}  		\
				else if(item_type == 2) {item = create_object(get_obj_index(TES_OBJ_WEAPON_DREMORA_CUTLASS   ), 0);}  		\
				else if(item_type == 3) {item = create_object(get_obj_index(TES_OBJ_WEAPON_DREMORA_SABER     ), 0);}  		\
				else if(item_type == 4) {item = create_object(get_obj_index(TES_OBJ_WEAPON_DREMORA_FALCHION  ), 0);}  		\
				else if(item_type == 5) {item = create_object(get_obj_index(TES_OBJ_WEAPON_DREMORA_KATANA    ), 0);}  		\
				else if(item_type == 6) {item = create_object(get_obj_index(TES_OBJ_WEAPON_DREMORA_LONGSWORD ), 0);}  		\
				else if(item_type == 7) {item = create_object(get_obj_index(TES_OBJ_WEAPON_DREMORA_BROADSWORD), 0);}  		\
				else if(item_type == 8) {item = create_object(get_obj_index(TES_OBJ_WEAPON_DREMORA_CLAYMORE  ), 0);}  		\
				else                    {item = create_object(get_obj_index(TES_OBJ_WEAPON_DREMORA_DAIKATANA ), 0);}  		\
