					 if(item_type == 1) {item = create_object(get_obj_index(TES_OBJ_WEAPON_DREMORA_DAGGER    ), 0);}  		\
				else if(item_type == 2) {item = create_object(get_obj_index(TES_OBJ_WEAPON_DREMORA_DIRK      ), 0);}  		\
