				item_type = number_range(1,3);                                                                        		\
					 if(item_type == 1) {item = create_object(get_obj_index(TES_OBJ_WEAPON_DREMORA_THROWING_DART ), 0);}	\
				else if(item_type == 2) {item = create_object(get_obj_index(TES_OBJ_WEAPON_DREMORA_THROWING_STAR ), 0);}	\
