	CHAR_DATA *victim = (CHAR_DATA *) vo; 
	CHAR_DATA *creature = NULL;
	AFFECT_DATA af;

	DREAMWALK_MANUAL_EFFECT_APPLIED = FALSE;
	if (!ch || !victim) return;
	int total_magicka = 0;
	
	#undef MAGICKA_CHECK
	#define MAGICKA_CHECK(var)                    \
		if(var <= ch->number_effects)             \
			total_magicka += ch->af##var##_cost;
			
	MAGICKA_CHECK(1); MAGICKA_CHECK(2); MAGICKA_CHECK(3); MAGICKA_CHECK(4); MAGICKA_CHECK(5); 
