ch_ret MANUAL_SPELL_DAMAGE_FIRE						(int sn, int level, CHAR_DATA *ch, void *vo){
//--------------------------------------------------------------------------------------------------//
	ch->number_effects 	= 1;	
	RESET_EFFECT_VARIABLES(ch);		
	ch->af1_name 		= "fire damage"; ch->af1_effect = "damaging %s health with fire"; 
	ch->af1_skill 		= "destruction"; 
	ch->af1_resistance 	= "fire";
	ch->af1_type 		= sn; 
	ch->af1_mmin 		= 10; 
	ch->af1_mmax 		= 20; 
	ch->af1_cost 		= 15;
	EFFECT_TYPE_MANUAL_ELEMENTAL_DAMAGE(sn, ch, vo);
	return DREAMWALK_MANUAL_EFFECT_APPLIED ? rNONE : rSPELL_FAILED;}
