ch_ret MANUAL_SPELL_DETECT_KEYS						(int sn, int level, CHAR_DATA *ch, void *vo){
//--------------------------------------------------------------------------------------------------//
	OBJ_DATA *obj;
	EXIT_DATA *pexit;
	bool found = FALSE;

	if(!ch || !ch->in_room) return rSPELL_FAILED;
	if(is_affected(ch, tes_effect_silence)) {{char cMSG[MAX_STRING_LENGTH]; sprintf(cMSG, "%s", "You are silenced."); act(AT_PLAIN, "$t", ch, cMSG, NULL, TO_CHAR);} return rSPELL_FAILED;}
	if(ch->mana < 15) {{char cMSG[MAX_STRING_LENGTH]; sprintf(cMSG, "%s", "You dont have enough magicka."); act(AT_PLAIN, "$t", ch, cMSG, NULL, TO_CHAR);} return rSPELL_FAILED;}

	ch->mana -= 15;

	for(obj = ch->in_room->first_content; obj; obj = obj->next_content)
	{
		if(obj->item_type != ITEM_KEY) continue;
		{char cMSG[MAX_STRING_LENGTH]; sprintf(cMSG, "%s", "&BYou sense a key right here.&D"); act(AT_PLAIN, "$t", ch, cMSG, NULL, TO_CHAR);}
		found = TRUE;
		break;
	}

	for(pexit = ch->in_room->first_exit; pexit; pexit = pexit->next)
	{
		if(!pexit->to_room) continue;

		for(obj = pexit->to_room->first_content; obj; obj = obj->next_content)
		{
			if(obj->item_type != ITEM_KEY) continue;
			{char cMSG[MAX_STRING_LENGTH]; sprintf(cMSG, "&BYou sense a key to the %s.&D", dir_name[pexit->vdir]); act(AT_PLAIN, "$t", ch, cMSG, NULL, TO_CHAR);}
			found = TRUE;
			break;
		}
	}

	if(!found) {char cMSG[MAX_STRING_LENGTH]; sprintf(cMSG, "%s", "You sense no keys nearby."); act(AT_PLAIN, "$t", ch, cMSG, NULL, TO_CHAR);}
	return rNONE;
}	
