ch_ret MANUAL_SPELL_ABSORB_RANDOM_ATTRIBUTE			(int sn, int level, CHAR_DATA *ch, void *vo){

	ch->number_effects 	= 2;
	RESET_EFFECT_VARIABLES(ch);

	int choice = number_range(1,7);
	     if (choice == 1) {ch->af1_name = "drain strength"; ch->af1_effect = "absorbing energy to fortify %s strength";     ch->af1_location = APPLY_STR;}
	else if (choice == 2) {ch->af1_name = "drain endurance"; ch->af1_effect = "absorbing energy to fortify %s endurance";    ch->af1_location = APPLY_CON;}
	else if (choice == 3) {ch->af1_name = "drain agility"; ch->af1_effect = "absorbing energy to fortify %s agility";      ch->af1_location = APPLY_DEX;}
	else if (choice == 4) {ch->af1_name = "drain intelligence"; ch->af1_effect = "absorbing energy to fortify %s intelligence"; ch->af1_location = APPLY_INT;}
	else if (choice == 5) {ch->af1_name = "drain willpower"; ch->af1_effect = "absorbing energy to fortify %s willpower";    ch->af1_location = APPLY_WIS;}
	else if (choice == 6) {ch->af1_name = "drain personality"; ch->af1_effect = "absorbing energy to fortify %s personality";  ch->af1_location = APPLY_CHA;}
	else 				  {ch->af1_name = "drain luck"; ch->af1_effect = "absorbing energy to fortify %s luck";  	    ch->af1_location = APPLY_LCK;}

	ch->af1_skill 		= "mysticism"; 
	ch->af1_target 		= "ch";	
	ch->af1_type 		= sn; 
	ch->af1_mmin 		= +1; 
	ch->af1_mmax 		= +4; 
	ch->af1_dmin 		= 20; 
	ch->af1_dmax 		= 20;	
	ch->af1_cost 		= 15;
	
	     if (choice == 1) {ch->af2_name = "drain strength"; ch->af2_effect = "draining %s strength";     ch->af2_location = APPLY_STR;}
	else if (choice == 2) {ch->af2_name = "drain endurance"; ch->af2_effect = "draining %s endurance";    ch->af2_location = APPLY_CON;}
	else if (choice == 3) {ch->af2_name = "drain agility"; ch->af2_effect = "draining %s agility";      ch->af2_location = APPLY_DEX;}
	else if (choice == 4) {ch->af2_name = "drain intelligence"; ch->af2_effect = "draining %s intelligence"; ch->af2_location = APPLY_INT;}
	else if (choice == 5) {ch->af2_name = "drain willpower"; ch->af2_effect = "draining %s willpower";    ch->af2_location = APPLY_WIS;}
	else if (choice == 6) {ch->af2_name = "drain personality"; ch->af2_effect = "draining %s personality";  ch->af2_location = APPLY_CHA;}
	else 				  {ch->af2_name = "drain luck"; ch->af2_effect = "draining %s luck";  	      ch->af2_location = APPLY_LCK;}

	ch->af2_skill 		= "mysticism"; 
	ch->af2_target 		= "victim";	
	ch->af2_type 		= sn; 
	ch->af2_mmin 		= -4; 
	ch->af2_mmax 		= -1; 
	ch->af2_dmin 		= 20; 
	ch->af2_dmax 		= 20;	
	ch->af2_cost 		= 15;

	EFFECT_TYPE_MANUAL_MODIFY_ATTRIBUTE(sn, ch, vo);
	return DREAMWALK_MANUAL_EFFECT_APPLIED ? rNONE : rSPELL_FAILED;	}
