//==================================================================================================//
ch_ret MANUAL_SPELL_DAMAGE_RANDOM_ATTRIBUTE			(int sn, int level, CHAR_DATA *ch, void *vo){
	
	ch->number_effects 	= 1;
	RESET_EFFECT_VARIABLES(ch);
	
	int choice = number_range(1,7);
	     if (choice == 1) {ch->af1_name = "damage strength"; ch->af1_effect = "damaging %s strength";     ch->af1_location = APPLY_STR;} 
	else if (choice == 2) {ch->af1_name = "damage endurance"; ch->af1_effect = "damaging %s endurance";    ch->af1_location = APPLY_CON;}
	else if (choice == 3) {ch->af1_name = "damage agility"; ch->af1_effect = "damaging %s agility";      ch->af1_location = APPLY_DEX;}
	else if (choice == 4) {ch->af1_name = "damage intelligence"; ch->af1_effect = "damaging %s intelligence"; ch->af1_location = APPLY_INT;}
	else if (choice == 5) {ch->af1_name = "damage willpower"; ch->af1_effect = "damaging %s willpower";    ch->af1_location = APPLY_WIS;}
	else if (choice == 6) {ch->af1_name = "damage personality"; ch->af1_effect = "damaging %s personality";  ch->af1_location = APPLY_CHA;}
	else 				  {ch->af1_name = "damage luck"; ch->af1_effect = "damaging %s luck";  	     ch->af1_location = APPLY_LCK;}
	

	ch->af1_skill 		= "destruction"; 
	ch->af1_target 		= "victim";	
	ch->af1_resistance 	= "magic";
	ch->af1_type 		= sn; 
	ch->af1_mmin 		= -2; 
	ch->af1_mmax 		= -1; 
	ch->af1_cost 		= 15;
	
	EFFECT_TYPE_MANUAL_CHANGE_ATTRIBUTE(sn, ch, vo);
	return DREAMWALK_MANUAL_EFFECT_APPLIED ? rNONE : rSPELL_FAILED;}
