ch_ret MANUAL_SPELL_DREAMWALK						(int sn, int level, CHAR_DATA *ch, void *vo){
  CHAR_DATA *victim = (CHAR_DATA *) vo;
  char buf1[256], buf2[256], buf3[256];
  AFFECT_DATA af;

	ch_printf(ch, "&CYou close your eyes and begin dreamwalking.&D\r\n");
	
  if(is_affected(victim, sn))
    {
    if(victim == ch)
      {
      act(AT_MAGIC, "You are already affected with this.", ch, NULL, victim, TO_CHAR);
      return rSPELL_FAILED;
      }
    if(victim != ch) 
      {
      act(AT_MAGIC, "$N is already affected with this.", ch, NULL, victim, TO_CHAR);
      return rSPELL_FAILED;
      }
    }

  af.type = sn;
  af.duration = 200;
  af.location = APPLY_AFFECT;
  af.modifier = 0;
  af.bitvector = meb(AFF_DREAMWALK);
  affect_to_char(victim, &af);

  snprintf(buf1, 256, "You are dreamwalking.");
  snprintf(buf2, 256, "$n is dreamwaking.");
  snprintf(buf3, 256, "$n is dreamwaking.");

  act(AT_MAGIC, buf1, ch, NULL, victim, TO_CHAR);
  act(AT_MAGIC, buf2, ch, NULL, victim, TO_VICT);
  act(AT_MAGIC, buf3, ch, NULL, victim, TO_NOTVICT);

  return rNONE;}
ch_ret MANUAL_SPELL_ARENA							(int sn, int level, CHAR_DATA *ch, void *vo){	
  CHAR_DATA *victim = (CHAR_DATA *) vo;
  char buf1[256], buf2[256], buf3[256];
  AFFECT_DATA af;

  if(is_affected(victim, sn))
    {
    if(victim == ch)
      {
      act(AT_MAGIC, "You are already affected with this.", ch, NULL, victim, TO_CHAR);
      return rSPELL_FAILED;
      }
    if(victim != ch) 
      {
      act(AT_MAGIC, "$N is already affected with this.", ch, NULL, victim, TO_CHAR);
      return rSPELL_FAILED;
      }
    }

  af.type = sn;
  af.duration = 20;
  af.location = APPLY_AFFECT;
  af.modifier = 0;
  af.bitvector = meb(AFF_ARENA);
  affect_to_char(victim, &af);

  snprintf(buf1, 256, "You are fighting in the arena.");
  snprintf(buf2, 256, "You are fighting in the arena.");
  snprintf(buf3, 256, "$n is fighting in the arena.");

  act(AT_MAGIC, buf1, ch, NULL, victim, TO_CHAR);
  act(AT_MAGIC, buf2, ch, NULL, victim, TO_VICT);
  act(AT_MAGIC, buf3, ch, NULL, victim, TO_NOTVICT);

  return rNONE;}
ch_ret MANUAL_SPELL_RESTORE_HEALTH_FREE				(int sn, int level, CHAR_DATA *ch, void *vo){
  CHAR_DATA *victim = (CHAR_DATA *) vo;
  char buf1[256], buf2[256], buf3[256];

  int effect;
  effect = number_range(1,100) + get_curr_wis(ch)/2;

  int cost;
  cost = 0;

  if(ch->mana < cost)
    {
    act(AT_MAGIC, "You don't have enough magicka.", ch, NULL, victim, TO_CHAR);
    return rSPELL_FAILED;
    }

  if(is_affected(ch, tes_effect_silence))
    {
    act(AT_MAGIC, "You are affected with silence and can't cast any spells.", ch, NULL, victim, TO_CHAR);
    return rSPELL_FAILED;
    }

  if(victim == ch)
    {
    snprintf(buf1, 256, "&BYou restore your health by %d points.&D", effect);
    snprintf(buf2, 256, "&B$n restores $s health.&D");
    snprintf(buf3, 256, "&B$n restores $s health.&D");
    }

  if(victim != ch)
    {
    snprintf(buf1, 256, "&BYou restore $N's health by %d points.&D", effect);
    snprintf(buf2, 256, "&B$n restores your health by %d points.&D", effect);
    snprintf(buf3, 256, "&B$n restores $N's health.&D");
    }

  act(AT_MAGIC, buf1, ch, NULL, victim, TO_CHAR);
  act(AT_MAGIC, buf2, ch, NULL, victim, TO_VICT);
  act(AT_MAGIC, buf3, ch, NULL, victim, TO_NOTVICT);

  victim->hit = victim->hit + effect;

  if(victim->hit > victim->max_hit)
    {
    int difference;
    difference = victim->hit - victim->max_hit;
    victim->hit = victim->hit - difference;
    }  

  ch->mana = ch->mana - cost;

  return rNONE;}
ch_ret MANUAL_SPELL_DAMAGE_SILVER					(int sn, int level, CHAR_DATA *ch, void *vo){
	char cMSG[256]; CHAR_DATA *victim = (CHAR_DATA *) vo;
	int effect;

	if(is_affected(victim, tes_effect_lycanthropy))
    {
		effect = number_range(1,30); 
		global_retcode = damage(ch, victim, effect, tes_effect_damage_silver);
		snprintf(cMSG, 256, "You are burnt from silver."); 
		act(AT_FIRE, cMSG, ch, NULL, NULL, TO_CHAR);
		return rNONE;
    }

	return rSPELL_FAILED;}
ch_ret MANUAL_SPELL_LOCK_PROCEDURE					(int sn, int level, CHAR_DATA *ch, void *vo) {
	OBJ_DATA *key;

	key = create_object(get_obj_index(TES_OBJ_VNUM_KEY), 0);
	obj_to_char(key, ch);

	if(time_info.hour > 8 && time_info.hour < 20)
    {
		do_unlock(ch, "east"); 	do_open(ch, "east");
		do_unlock(ch, "west"); 	do_open(ch, "west");
		do_unlock(ch, "north"); do_open(ch, "north");
		do_unlock(ch, "south"); do_open(ch, "south");
		do_say(ch, "opening");
    }
	else
    {
		do_close(ch, "east");  do_lock(ch, "east");
		do_close(ch, "west");  do_lock(ch, "west");

		do_close(ch, "north"); do_lock(ch, "north");
		do_close(ch, "south"); do_lock(ch, "south"); 
		do_say(ch, "closing");
    }

	return rNONE;}
