ch_ret PASSIVE_SPELL_ARMOR_PARALYSIS				(int sn, int level, CHAR_DATA *ch, void *vo){
	CHAR_DATA *victim = (CHAR_DATA *) vo; AFFECT_DATA af;
	int dice, chance;

	int effect_dice = number_percent();
	int effect_chance    = 90;
	int effect_duration  = 3;

	if(effect_dice < effect_chance)
		{if(!is_affected(victim, sn)) {af.type = sn; af.duration = effect_duration; af.location = APPLY_AFFECT; af.modifier = 0; af.bitvector = meb(AFF_PARALYSIS); affect_to_char(victim, &af);}}
		return rNONE;} 
